const e="clinicreport",t="ClinicReport",i={aspnetEndpoints:["src/ClinicReport.Api"],efSnapshots:[{file:"src/ClinicReport.Api/Data/Migrations/ClinicReportDbContextModelSnapshot.cs",database:"clinicreport-{clinic}.db",provider:"sqlite"}],reactRoutes:"web/src/App.tsx"},n=[{id:"start",title:{en:"Getting started",fa:"شروع"}},{id:"templates",title:{en:"Templates: the form is data",fa:"قالب‌ها: فرم، داده است"}},{id:"reports",title:{en:"Writing a report",fa:"نوشتن گزارش"}},{id:"security",title:{en:"Accounts and security",fa:"حساب‌ها و امنیت"}},{id:"clinichub",title:{en:"With ClinicHub: sign-in, orders, results",fa:"با ClinicHub: ورود، درخواست‌ها، جواب‌ها"}},{id:"frontend",title:{en:"Frontend (React)",fa:"فرانت‌اند (React)"}},{id:"data",title:{en:"Data (SQLite)",fa:"داده (SQLite)"}}],s=[{id:"run",group:"start",title:{en:"Run it: Docker or the PC",fa:"اجرا: Docker یا PC"},files:["README.md","Dockerfile","docker-compose.yml","src/ClinicReport.Api/Properties/launchSettings.json","src/ClinicReport.Api/Program.cs"],en:[{id:"docker",h:"One container, one volume",p:["The image builds the React app with Node, publishes the API with the .NET SDK, and copies both into the ASP.NET runtime image: the API serves the page from `wwwroot`. Everything that must survive a redeploy lives in `/data`: the SQLite database (one file, or one per clinic) and the keys that encrypt the sign-in cookie.","`docker compose up -d` and then `docker compose logs clinicreport`: the first start prints a generated password for `admin`, who must choose a new one at once."],examples:["image"]},{id:"pc",h:"On the PC, three profiles",p:["`dotnet run --project src/ClinicReport.Api` serves the API on http://localhost:5290 and `npm --prefix web run dev` the page on http://localhost:5291. The `http` profile is standalone with demo data; `connected` signs in through ClinicHub on :5301 and sends the accounting to FinancePowerApp on :5400; `via-hub` sends results and accounting through IntegrationHub on :5700 instead."],examples:["profile"]},{id:"start",h:"What happens at start",p:["Standalone, the one database is migrated and seeded before the first request (roles, the bundled templates, the demo, the first admin). Connected, nothing is prepared at start: each clinic's database is created at its first sign-in."],examples:["init"]},{id:"server",h:"On the server, twice",p:["Control Panel runs it twice. `clinicreport` is the public demo at report.arashkeshtgar.ca: synthetic patients, one-click demo users, wiped every day at 08:00 UTC. `clinicreport-clinic` is the clinic's own, signed in through ClinicHub with its results and accounting going through IntegrationHub. How the server and Caddy are set up is in Control Panel's topics (deploy-vps)."]}],fa:[{id:"docker",h:"یک container، یک volume",p:["image اپ React را با Node build می‌کند، API را با .NET SDK publish می‌کند، و هر دو را در image زمان اجرای ASP.NET کپی می‌کند: API صفحه را از `wwwroot` سرو می‌کند. هر چیزی که باید از یک redeploy جان سالم به در ببرد در `/data` است: دیتابیس SQLite (یک فایل، یا یکی برای هر کلینیک) و کلیدهایی که کوکی ورود را رمز می‌کنند.","`docker compose up -d` و بعد `docker compose logs clinicreport`: اولین اجرا یک رمز ساخته‌شده برای `admin` چاپ می‌کند، که باید همان اول یک رمز تازه انتخاب کند."],examples:["image"]},{id:"pc",h:"روی PC، سه profile",p:["`dotnet run --project src/ClinicReport.Api` API را روی http://localhost:5290 بالا می‌آورد و `npm --prefix web run dev` صفحه را روی http://localhost:5291. profile `http` مستقل است و داده‌ی دمو دارد؛ `connected` ورود را از ClinicHub روی :5301 می‌گیرد و حسابداری را به FinancePowerApp روی :5400 می‌فرستد؛ `via-hub` جواب‌ها و حسابداری را به‌جایش از IntegrationHub روی :5700 رد می‌کند."],examples:["profile"]},{id:"start",h:"موقع بالا آمدن چه می‌شود",p:["در حالت مستقل، تنها دیتابیس قبل از اولین درخواست migrate و seed می‌شود (نقش‌ها، قالب‌های همراه، دمو، اولین admin). در حالت متصل، موقع بالا آمدن هیچ چیز آماده نمی‌شود: دیتابیس هر کلینیک در اولین ورودش ساخته می‌شود."],examples:["init"]},{id:"server",h:"روی سرور، دو بار",p:["Control Panel آن را دو بار اجرا می‌کند. `clinicreport` دموی عمومی روی report.arashkeshtgar.ca است: بیمارهای ساختگی، کاربران دمو با یک کلیک، و هر روز ساعت 08:00 UTC پاک می‌شود. `clinicreport-clinic` مال خود کلینیک است، با ورود از ClinicHub، و جواب‌ها و حسابداری‌اش از IntegrationHub می‌گذرند. این‌که سرور و Caddy چطور راه افتاده‌اند در topicهای Control Panel آمده (deploy-vps)."]}],examples:{image:{title:{en:"The runtime stage of the Dockerfile",fa:"مرحله‌ی runtime در Dockerfile"},lang:"dockerfile",file:"Dockerfile",from:"FROM mcr.microsoft.com/dotnet/aspnet:10.0",to:"ENTRYPOINT"},profile:{title:{en:"The connected profile",fa:"profile متصل"},lang:"json",file:"src/ClinicReport.Api/Properties/launchSettings.json",from:'"connected": {',lines:15},init:{title:{en:"One database now, or one per clinic later",fa:"یک دیتابیس الان، یا یکی برای هر کلینیک بعداً"},lang:"csharp",file:"src/ClinicReport.Api/Program.cs",from:"// Standalone: one database, prepared now.",lines:5}},quiz:[{q:{en:"The container is redeployed. Why are people not signed out and the reports not lost?",fa:"کانتینر دوباره deploy می‌شود. چرا افراد خارج نمی‌شوند و گزارش‌ها از بین نمی‌روند؟"},options:{en:["The image contains a copy of the database","The SQLite files and the cookie keys live in the `/data` volume","The browser keeps the reports offline"],fa:["image یک نسخه از دیتابیس را دارد","فایل‌های SQLite و کلیدهای کوکی در volume‌ی `/data` هستند","مرورگر گزارش‌ها را آفلاین نگه می‌دارد"]},answer:1,why:{en:"Everything that must survive a redeploy is in `/data`; the image itself is replaced.",fa:"هر چیزی که باید از redeploy جان سالم به در ببرد در `/data` است؛ خود image عوض می‌شود."}},{q:{en:"ClinicReport starts connected to ClinicHub. What is prepared at start?",fa:"ClinicReport متصل به ClinicHub شروع می‌شود. موقع شروع چه چیزی آماده می‌شود؟"},options:{en:["Nothing: each clinic's database is created at its first sign-in","One database for every clinic ClinicHub knows","The demo patients"],fa:["هیچ: دیتابیس هر کلینیک در اولین ورودش ساخته می‌شود","یک دیتابیس برای هر کلینیکی که ClinicHub می‌شناسد","بیماران دمو"]},answer:0,why:{en:"Only standalone migrates and seeds its one database before the first request.",fa:"فقط حالت مستقل دیتابیس تنهایش را قبل از اولین درخواست migrate و seed می‌کند."}},{q:{en:"How does the first administrator of a fresh standalone install get in?",fa:"اولین مدیر یک نصب مستقل تازه چطور وارد می‌شود؟"},options:{en:["With a password written in the Dockerfile","Through ClinicHub","With a generated password printed in the log, which must be changed at once"],fa:["با رمزی که در Dockerfile نوشته شده","از طریق ClinicHub","با رمزی تولیدشده که در لاگ چاپ می‌شود و باید فوراً عوض شود"]},answer:2,why:{en:"`docker compose logs clinicreport` shows it on the first start; `admin` must choose a new one before anything else.",fa:"`docker compose logs clinicreport` آن را در اولین شروع نشان می‌دهد؛ `admin` باید قبل از هر کاری رمز تازه انتخاب کند."}}]},{id:"tests",group:"start",title:{en:"Tests and CI",fa:"تست‌ها و CI"},files:["tests/ClinicReport.Tests/ApiTests.cs","tests/ClinicReport.Tests/ConnectedTests.cs",".github/workflows/ci.yml"],en:[{id:"api",h:"The real API on a throwaway database",p:["`dotnet test` runs 60+ tests. Most go over HTTP through `WebApplicationFactory`: each test class gets a fresh SQLite file in the temp folder with the demo data, signs in as a demo user and calls the API the way the page does, CSRF header included. The domain (formulas, renderer, validator) is tested on its own, without I/O."],examples:["factory"]},{id:"parallel",h:"Two people typing at once",p:["The test that matters most for co-editing: a typist and a physician save ten fields of the same report at the same time. Every value must be kept, and the revision must have gone up once per save."],examples:["parallel"]},{id:"connected",h:"ClinicHub, played by the test",p:["ClinicHub is another project, so the connected tests stand in for it: a fixed discovery document, a token endpoint whose answer the test chooses, and a receiver that records the results it is sent."],examples:["fakehub"]},{id:"ci",h:"CI ends with the image",p:["GitHub Actions runs the .NET tests, builds and tests the page, then builds the Docker image and starts it: `/healthz` must answer, `/` must be the React page, and the log must say the echo template was imported."],examples:["smoke"]}],fa:[{id:"api",h:"API واقعی روی یک دیتابیس دورریختنی",p:["`dotnet test` بیش از ۶۰ تست اجرا می‌کند. بیشترشان از HTTP و با `WebApplicationFactory` می‌روند: هر کلاس تست یک فایل SQLite تازه در پوشه‌ی temp با داده‌ی دمو می‌گیرد، با یک کاربر دمو وارد می‌شود و API را همان‌طور صدا می‌زند که صفحه می‌زند، با هدر CSRF. domain (فرمول‌ها، renderer، validator) جدا و بدون I/O تست می‌شود."],examples:["factory"]},{id:"parallel",h:"دو نفر هم‌زمان تایپ می‌کنند",p:["مهم‌ترین تست برای ویرایش هم‌زمان: یک تایپیست و یک پزشک ده فیلد یک گزارش را هم‌زمان ذخیره می‌کنند. همه‌ی مقدارها باید بمانند، و revision باید به ازای هر ذخیره یک بار بالا رفته باشد."],examples:["parallel"]},{id:"connected",h:"ClinicHub، با بازی تست",p:["ClinicHub پروژه‌ی دیگری است، پس تست‌های حالت متصل جایش را می‌گیرند: یک discovery document ثابت، یک token endpoint که جوابش را تست انتخاب می‌کند، و گیرنده‌ای که جواب‌هایی را که برایش فرستاده می‌شود ثبت می‌کند."],examples:["fakehub"]},{id:"ci",h:"CI با image تمام می‌شود",p:["GitHub Actions تست‌های .NET را اجرا می‌کند، صفحه را build و تست می‌کند، بعد image داکر را می‌سازد و اجرا می‌کند: `/healthz` باید جواب بدهد، `/` باید صفحه‌ی React باشد، و log باید بگوید قالب اکو import شده."],examples:["smoke"]}],examples:{factory:{title:{en:"A fresh database per test class",fa:"یک دیتابیس تازه برای هر کلاس تست"},lang:"csharp",file:"tests/ClinicReport.Tests/ApiTests.cs",from:"protected override void ConfigureWebHost(IWebHostBuilder builder)",lines:8},parallel:{title:{en:"Ten fields, two people, at once",fa:"ده فیلد، دو نفر، هم‌زمان"},lang:"csharp",file:"tests/ClinicReport.Tests/ApiTests.cs",from:"public async Task Parallel_edits_to_different_fields_are_all_kept()",lines:15},fakehub:{title:{en:"Why ClinicHub is a stand-in",fa:"چرا ClinicHub جانشین دارد"},lang:"csharp",file:"tests/ClinicReport.Tests/ConnectedTests.cs",from:"/// ClinicReport connected to ClinicHub.",lines:4},smoke:{title:{en:"The smoke test",fa:"smoke test"},lang:"yaml",file:".github/workflows/ci.yml",from:"- name: Smoke test",lines:7}},quiz:[{q:{en:"What does each API test class get as its database?",fa:"هر کلاس تست API چه دیتابیسی می‌گیرد؟"},options:{en:["A shared test database cleaned between tests","A fresh SQLite file in the temp folder, with the demo data","An in-memory list instead of a database"],fa:["یک دیتابیس تست مشترک که بین تست‌ها پاک می‌شود","یک فایل SQLite تازه در پوشه‌ی temp، با داده‌ی دمو","یک فهرست در حافظه به‌جای دیتابیس"]},answer:1,why:{en:"`WebApplicationFactory` points the real API at a throwaway file, so tests go through HTTP as the page does.",fa:"`WebApplicationFactory` API واقعی را به یک فایل یک‌بارمصرف وصل می‌کند، تا تست‌ها مثل صفحه از HTTP عبور کنند."}},{q:{en:"A typist and a physician save ten different fields of one report at once. What must the test find?",fa:"یک تایپیست و یک پزشک هم‌زمان ده فیلد مختلف از یک گزارش را ذخیره می‌کنند. تست باید چه چیزی پیدا کند؟"},options:{en:["Only the last save's fields","A conflict error for the slower one","Every value kept, and the revision raised once per save"],fa:["فقط فیلدهای آخرین ذخیره","خطای تداخل برای کندتر","همه‌ی مقدارها نگه داشته شده و revision برای هر ذخیره یک بار بالا رفته"]},answer:2,why:{en:"Co-editing must never lose an answer; that is what the concurrency retry in the service is for.",fa:"ویرایش هم‌زمان نباید هیچ جوابی را گم کند؛ تلاش دوباره‌ی همزمانی در سرویس برای همین است."}},{q:{en:"What does the CI smoke test check after building the Docker image?",fa:"smoke test در CI بعد از ساختن image داکر چه چیزی را چک می‌کند؟"},options:{en:["`/healthz` answers, `/` is the React page, and the log says the echo template was imported","That the image is under a size limit","That ClinicHub accepts a result"],fa:["`/healthz` جواب می‌دهد، `/` صفحه‌ی React است، و لاگ می‌گوید قالب اکو وارد شده","این‌که image از یک اندازه کوچک‌تر است","این‌که ClinicHub یک جواب را قبول می‌کند"]},answer:0,why:{en:"Starting the real image catches what unit tests cannot: the page copied into `wwwroot` and the bundled templates found.",fa:"اجرای image واقعی چیزی را می‌گیرد که تست واحد نمی‌گیرد: صفحه‌ای که در `wwwroot` کپی شده و قالب‌های همراه که پیدا شده‌اند."}}]},{id:"template-model",group:"templates",title:{en:"A template: sections, fields, phrases",fa:"یک قالب: بخش‌ها، فیلدها، جمله‌ها"},files:["src/ClinicReport.Api/Domain/TemplateDefinition.cs","templates/echo-tte.json","docs/templates.md"],en:[{id:"idea",h:"The answer carries the sentence",p:["Each service the clinic reports on (echo, ECG…) is a template: JSON, not code. A template has sections; a section has fields; a choice field has options, and each option carries the sentence it adds to the report. Clicking *Stenosis → Moderate* writes “There is moderate mitral stenosis.”; *None* has an empty phrase and writes nothing.","A field can have children that appear only for some answers (`showIf`): the mean gradient and the valve area are asked only when there is stenosis."],examples:["echo"]},{id:"types",h:"Six field types",p:["`choice` (one option), `multi` (several), `number` (a typed measurement), `computed` (a formula over other numbers), `text` and `textarea`. Only the first two have options, only numbers have normal ranges, only `computed` has a formula: the validator enforces each of these."],examples:["types"]},{id:"ranges",h:"Normal ranges by sex",p:["A range can be one pair of bounds or a pair for men and one for women, with its source (e.g. ASE/EACVI 2015) for whoever edits the template. The patient's sex picks the bounds; when there is none for that sex, the common one is used."],examples:["range"]},{id:"strict",h:"A typo fails loudly",p:['The JSON is read with `UnmappedMemberHandling.Disallow`: a misspelt `"phrse"` is an error, not a phrase that silently disappears from every report.'],examples:["strict"]}],fa:[{id:"idea",h:"جواب، جمله‌اش را با خودش دارد",p:["هر سرویسی که کلینیک برایش گزارش می‌نویسد (اکو، ECG…) یک قالب است: JSON، نه کد. قالب بخش دارد؛ بخش فیلد دارد؛ فیلد choice گزینه دارد، و هر گزینه جمله‌ای را که به گزارش اضافه می‌کند با خودش دارد. کلیک روی *Stenosis → Moderate* می‌نویسد «There is moderate mitral stenosis.»؛ *None* جمله‌ی خالی دارد و هیچ چیز نمی‌نویسد.","یک فیلد می‌تواند فرزندانی داشته باشد که فقط برای بعضی جواب‌ها ظاهر می‌شوند (`showIf`): گرادیان میانگین و مساحت دریچه فقط وقتی پرسیده می‌شوند که تنگی باشد."],examples:["echo"]},{id:"types",h:"شش نوع فیلد",p:["`choice` (یک گزینه)، `multi` (چند گزینه)، `number` (اندازه‌ی تایپ‌شده)، `computed` (فرمولی روی عددهای دیگر)، `text` و `textarea`. فقط دو تای اول گزینه دارند، فقط عددها محدوده‌ی نرمال دارند، فقط `computed` فرمول دارد: validator هر کدام را اجبار می‌کند."],examples:["types"]},{id:"ranges",h:"محدوده‌ی نرمال بر اساس جنس",p:["محدوده می‌تواند یک جفت حد باشد یا یک جفت برای مردها و یکی برای زن‌ها، همراه منبعش (مثلاً ASE/EACVI 2015) برای کسی که قالب را ویرایش می‌کند. جنس بیمار حدها را انتخاب می‌کند؛ اگر برای آن جنس حدی نباشد، حد مشترک به کار می‌رود."],examples:["range"]},{id:"strict",h:"غلط تایپی با صدای بلند خطا می‌دهد",p:['JSON با `UnmappedMemberHandling.Disallow` خوانده می‌شود: یک `"phrse"` غلط‌املایی خطاست، نه جمله‌ای که بی‌صدا از همه‌ی گزارش‌ها غیب شود.'],examples:["strict"]}],examples:{echo:{title:{en:"Mitral stenosis in the echo template",fa:"تنگی میترال در قالب اکو"},lang:"json",file:"templates/echo-tte.json",from:'"id": "ms", "label": "Stenosis"',lines:20},types:{title:{en:"The field types",fa:"نوع‌های فیلد"},lang:"csharp",file:"src/ClinicReport.Api/Domain/TemplateDefinition.cs",from:"public static class FieldTypes",lines:13},range:{title:{en:"The bounds for this patient",fa:"حدهای این بیمار"},lang:"csharp",file:"src/ClinicReport.Api/Domain/TemplateDefinition.cs",from:"public Bounds? For(string? sex) => sex switch",lines:7},strict:{title:{en:"Unknown properties are errors",fa:"property ناشناخته خطاست"},lang:"csharp",file:"src/ClinicReport.Api/Domain/TemplateDefinition.cs",from:"// A misspelt property",lines:2}},quiz:[{q:{en:'Where does the sentence "There is moderate mitral stenosis." come from?',fa:"جمله‌ی «There is moderate mitral stenosis.» از کجا می‌آید؟"},options:{en:["The phrase of the option *Moderate* in the template","A C# switch over field names","The physician types it"],fa:["phrase‌ی گزینه‌ی *Moderate* در قالب","یک switch در C# روی اسم فیلدها","پزشک آن را تایپ می‌کند"]},answer:0,why:{en:"Each option carries the sentence it adds, so a template is data, not code.",fa:"هر گزینه جمله‌ای را که اضافه می‌کند با خودش دارد، پس قالب داده است نه کد."}},{q:{en:'A template author writes `"phrse"` instead of `"phrase"`. What happens?',fa:'نویسنده‌ی قالب به‌جای `"phrase"` می‌نویسد `"phrse"`. چه می‌شود؟'},options:{en:["The option silently has no sentence","Reading the JSON fails with an error","The misspelling is corrected automatically"],fa:["گزینه بی‌صدا جمله‌ای ندارد","خواندن JSON با خطا شکست می‌خورد","غلط املایی خودکار درست می‌شود"]},answer:1,why:{en:"`UnmappedMemberHandling.Disallow` makes an unknown property an error instead of a phrase lost from every report.",fa:"`UnmappedMemberHandling.Disallow` یک property ناشناخته را خطا می‌کند به‌جای جمله‌ای که از همه‌ی گزارش‌ها گم شود."}},{q:{en:"A range has bounds for men and for women, and the patient's sex is `U`. Which bounds apply?",fa:"یک محدوده برای مرد و زن حد دارد و جنس بیمار `U` است. کدام حدها اعمال می‌شوند؟"},options:{en:["The men's","None: the number is not flagged","The common bounds, when the range has them"],fa:["حدهای مرد","هیچ: عدد flag نمی‌خورد","حدهای مشترک، اگر محدوده آن‌ها را داشته باشد"]},answer:2,why:{en:"The patient's sex picks the bounds; when there is none for that sex, the common one is used.",fa:"جنس بیمار حدها را انتخاب می‌کند؛ اگر برای آن جنس حدی نباشد، حد مشترک به کار می‌رود."}}]},{id:"formula",group:"templates",title:{en:"Calculated fields: a small, safe language",fa:"فیلدهای محاسبه‌ای: یک زبان کوچک و امن"},files:["src/ClinicReport.Api/Domain/Formula.cs"],en:[{id:"why",h:"Arithmetic, and nothing else",p:["BSA, LV mass index, E/e′, RVSP and QTc are formulas in the template, e.g. `sqrt(height * weight / 3600)`. They are parsed by a hand-written recursive-descent parser into a tree of numbers, field names, `+ - * / ^` and six functions. There is no `eval`, no reflection and no way to call anything else, so a template from anywhere can be imported safely."]},{id:"grammar",h:"One method per precedence level",p:["`ParseExpression` handles `+ -`, `ParseTerm` `* /`, `ParsePower` `^`, which calls itself on its right, so `2 ^ 3 ^ 2` is 2⁹ as in mathematics. Each function's argument count is checked while parsing, so a mistake shows in the designer, not in a report."],examples:["power","arity"]},{id:"null",h:"Missing is null, not an error",p:["A half-filled report is the normal state, so a missing input, a division by zero or the square root of a negative number give null: the computed field stays empty until it can be calculated. `avg` skips blanks, so E/e′ works with only the septal e′ measured."],examples:["binary","avg"]}],fa:[{id:"why",h:"حساب، و هیچ چیز دیگر",p:["BSA، LV mass index، E/e′، RVSP و QTc فرمول‌هایی در قالب‌اند، مثلاً `sqrt(height * weight / 3600)`. یک parser دست‌نویس recursive-descent آن‌ها را به درختی از عددها، اسم فیلدها، `+ - * / ^` و شش تابع تبدیل می‌کند. `eval` نیست، reflection نیست و راهی برای صدا زدن چیز دیگری نیست، پس قالبی که از هر جا آمده باشد را می‌شود بی‌خطر import کرد."]},{id:"grammar",h:"یک متد برای هر سطح اولویت",p:["`ParseExpression` به `+ -` می‌رسد، `ParseTerm` به `* /`، `ParsePower` به `^`، که سمت راستش خودش را صدا می‌زند، پس `2 ^ 3 ^ 2` مثل ریاضی 2⁹ است. تعداد آرگومان هر تابع موقع parse چک می‌شود، پس اشتباه در designer دیده می‌شود، نه در گزارش."],examples:["power","arity"]},{id:"null",h:"نبودن یعنی null، نه خطا",p:["گزارش نیمه‌پر حالت عادی است، پس ورودی گم‌شده، تقسیم بر صفر یا جذر عدد منفی null می‌دهند: فیلد محاسبه‌ای تا وقتی قابل حساب نباشد خالی می‌ماند. `avg` جاهای خالی را رد می‌کند، پس E/e′ فقط با e′ سپتال هم کار می‌کند."],examples:["binary","avg"]}],examples:{power:{title:{en:"Power is right associative",fa:"توان از راست شرکت‌پذیر است"},lang:"csharp",file:"src/ClinicReport.Api/Domain/Formula.cs",from:"// power := unary ('^' power)?",lines:11},arity:{title:{en:"Argument counts, checked while parsing",fa:"تعداد آرگومان‌ها، موقع parse"},lang:"csharp",file:"src/ClinicReport.Api/Domain/Formula.cs",from:"var (min, max) = name switch",lines:8},binary:{title:{en:"A missing side, or a zero divisor: null",fa:"یک طرف گم، یا مقسوم‌علیه صفر: null"},lang:"csharp",file:"src/ClinicReport.Api/Domain/Formula.cs",from:"private sealed record Binary(char Op, Node Left, Node Right) : Node",lines:17},avg:{title:{en:"avg ignores blanks",fa:"avg جای خالی را نمی‌شمارد"},lang:"csharp",file:"src/ClinicReport.Api/Domain/Formula.cs",from:'case "avg":',lines:9}},quiz:[{q:{en:"Why is a hand-written parser used instead of evaluating the formula as code?",fa:"چرا به‌جای اجرای فرمول به شکل کد، یک parser دست‌نویس استفاده می‌شود؟"},options:{en:["It is faster than compiled code","C# has no way to evaluate strings","A formula can only be arithmetic, so a template from anywhere can be imported safely"],fa:["از کد کامپایل‌شده سریع‌تر است","C# راهی برای اجرای رشته ندارد","فرمول فقط می‌تواند حساب باشد، پس قالب از هر جایی را می‌شود با خیال راحت وارد کرد"]},answer:2,why:{en:"No `eval`, no reflection: the tree has numbers, field names, operators and six functions, nothing else.",fa:"نه `eval`، نه reflection: درخت فقط عدد، اسم فیلد، عملگر و شش تابع دارد."}},{q:{en:"What is `2 ^ 3 ^ 2`?",fa:"`2 ^ 3 ^ 2` چند است؟"},options:{en:["64, read left to right","512, as in mathematics","An error: chained powers are refused"],fa:["۶۴، از چپ به راست","۵۱۲، مثل ریاضیات","خطا: توان‌های پشت‌سرهم رد می‌شوند"]},answer:1,why:{en:"`ParsePower` calls itself on its right, so `^` is right-associative: 2⁹.",fa:"`ParsePower` خودش را روی سمت راستش صدا می‌زند، پس `^` از راست شریک‌پذیر است: ۲ به توان ۹."}},{q:{en:"The weight has not been typed yet. What does the BSA field show?",fa:"وزن هنوز تایپ نشده. فیلد BSA چه نشان می‌دهد؟"},options:{en:["Nothing: the formula gives null until it can be calculated","An error message","Zero"],fa:["هیچ: فرمول تا وقتی قابل محاسبه نیست null می‌دهد","یک پیام خطا","صفر"]},answer:0,why:{en:"A half-filled report is normal, so a missing input is null, not an error.",fa:"گزارش نیمه‌پر حالت عادی است، پس ورودی جاافتاده null است نه خطا."}}]},{id:"renderer",group:"templates",title:{en:"From answers to a written report",fa:"از جواب‌ها به گزارش نوشته‌شده"},files:["src/ClinicReport.Api/Domain/ReportRenderer.cs","src/ClinicReport.Api/Domain/ReportValues.cs"],en:[{id:"what",h:"Four things out of one pass",p:["`ReportRenderer.Render` takes the template, the answers and the patient (sex, height, weight, age) and returns what the referring physician reads: one paragraph per section, a table of measurements with their ranges and H/L flags, the computed values, the abnormal findings (for the conclusion draft) and the required fields still empty (which block signing). It reads nothing and writes nothing, so the same code serves the editor, the designer's preview and the signature."]},{id:"sentence",h:"The sentence of a field",p:["A choice field uses its option's phrase, else the field's, else `{label}: {value}.`. Placeholders are filled, extra spaces and “ .” are removed, the first letter is capitalised and a full stop added if missing, so template authors can be careless about punctuation."],examples:["choice","fill"]},{id:"hidden",h:"Hidden answers say nothing",p:["A field is visible when its parent is and its `showIf` holds. A hidden field contributes nothing even if it still holds an old answer (stenosis set back to *None* leaves the gradient typed earlier out of the report), and a hidden number feeds no formula."],examples:["visible","number"]},{id:"flags",h:"H and L",p:["A measurement below its range is flagged L, above it H; a flagged number also counts as an abnormal finding."],examples:["flag"]}],fa:[{id:"what",h:"چهار چیز از یک دور",p:["`ReportRenderer.Render` قالب، جواب‌ها و بیمار (جنس، قد، وزن، سن) را می‌گیرد و چیزی را برمی‌گرداند که پزشک ارجاع‌دهنده می‌خواند: یک پاراگراف برای هر بخش، جدول اندازه‌ها با محدوده‌ها و flagهای H/L، مقدارهای محاسبه‌شده، یافته‌های غیرطبیعی (برای پیش‌نویس نتیجه‌گیری) و فیلدهای اجباری هنوز خالی (که جلوی امضا را می‌گیرند). هیچ چیز نمی‌خواند و هیچ چیز نمی‌نویسد، پس همان کد به ویرایشگر، پیش‌نمایش designer و امضا خدمت می‌کند."]},{id:"sentence",h:"جمله‌ی یک فیلد",p:["فیلد choice جمله‌ی گزینه‌اش را به کار می‌برد، وگرنه جمله‌ی فیلد، وگرنه `{label}: {value}.`. جای‌نگه‌دارها پر می‌شوند، فاصله‌های اضافه و « .» حذف می‌شوند، حرف اول بزرگ و اگر نقطه نباشد اضافه می‌شود، پس نویسنده‌ی قالب لازم نیست حواسش به نقطه‌گذاری باشد."],examples:["choice","fill"]},{id:"hidden",h:"جواب پنهان چیزی نمی‌گوید",p:["فیلد وقتی پیداست که والدش پیدا باشد و `showIf`اش برقرار. فیلد پنهان هیچ سهمی ندارد حتی اگر هنوز جواب قدیمی داشته باشد (تنگی‌ای که به *None* برگشته، گرادیان تایپ‌شده‌ی قبلی را از گزارش بیرون نگه می‌دارد)، و عدد پنهان به هیچ فرمولی نمی‌رسد."],examples:["visible","number"]},{id:"flags",h:"H و L",p:["اندازه‌ی کمتر از محدوده‌اش L می‌خورد و بیشتر از آن H؛ عدد flag‌خورده یافته‌ی غیرطبیعی هم حساب می‌شود."],examples:["flag"]}],examples:{choice:{title:{en:"A choice field's sentence",fa:"جمله‌ی فیلد choice"},lang:"csharp",file:"src/ClinicReport.Api/Domain/ReportRenderer.cs",from:"case FieldTypes.Choice:",lines:8},fill:{title:{en:"Tidying the sentence",fa:"مرتب کردن جمله"},lang:"csharp",file:"src/ClinicReport.Api/Domain/ReportRenderer.cs",from:"private static string? Fill(string phrase, FieldDef f, string value, string values)",lines:15},visible:{title:{en:"Visible: the parent, then the condition",fa:"پیدا: اول والد، بعد شرط"},lang:"csharp",file:"src/ClinicReport.Api/Domain/ReportRenderer.cs",from:"var visible = (_parents.GetValueOrDefault(fieldId)",lines:2},number:{title:{en:"A number only if its field is showing",fa:"عدد فقط اگر فیلدش پیدا باشد"},lang:"csharp",file:"src/ClinicReport.Api/Domain/ReportRenderer.cs",from:"/// <summary>A typed or computed number, but only if its field is showing.</summary>",lines:7},flag:{title:{en:"The flag",fa:"flag"},lang:"csharp",file:"src/ClinicReport.Api/Domain/ReportRenderer.cs",from:"private static string? Flag(Bounds? b, double value) =>",lines:5}},quiz:[{q:{en:"Why does `ReportRenderer.Render` read and write nothing?",fa:"چرا `ReportRenderer.Render` هیچ چیزی نمی‌خواند و نمی‌نویسد؟"},options:{en:["So the same code serves the editor, the designer's preview and the signature","Because SQLite allows one reader","To make it asynchronous"],fa:["تا همان کد هم ویرایشگر، هم پیش‌نمایش طراح و هم امضا را سرویس دهد","چون SQLite یک خواننده اجازه می‌دهد","برای این‌که async شود"]},answer:0,why:{en:"Given the template, answers and patient, it returns the text; callers decide where the data comes from.",fa:"با گرفتن قالب، جواب‌ها و بیمار، متن را برمی‌گرداند؛ صدازننده تصمیم می‌گیرد داده از کجا بیاید."}},{q:{en:"Stenosis is set back to *None*, but a gradient typed earlier is still stored. What does the report say about it?",fa:"تنگی دوباره *None* می‌شود، ولی gradientی که قبلاً تایپ شده هنوز ذخیره است. گزارش درباره‌اش چه می‌گوید؟"},options:{en:["The gradient, flagged as outdated","Nothing: a hidden field contributes nothing","The gradient, as before"],fa:["gradient، با علامت قدیمی","هیچ: فیلد پنهان چیزی اضافه نمی‌کند","gradient، مثل قبل"]},answer:1,why:{en:"Visibility follows the parent and `showIf`; a hidden number also feeds no formula.",fa:"دیده شدن از والد و `showIf` پیروی می‌کند؛ عدد پنهان به هیچ فرمولی هم نمی‌رسد."}},{q:{en:`A template's phrase is written as "moderate  stenosis .". What reaches the report?`,fa:"phrase‌ی یک قالب به شکل «moderate  stenosis .» نوشته شده. چه چیزی به گزارش می‌رسد؟"},options:{en:["Exactly the same text","Nothing, because the phrase is invalid",'"Moderate stenosis.": spaces tidied, first letter capitalised, one full stop'],fa:["دقیقاً همان متن","هیچ، چون phrase نامعتبر است","«Moderate stenosis.»: فاصله‌ها مرتب، حرف اول بزرگ، یک نقطه"]},answer:2,why:{en:"The renderer cleans punctuation so template authors can be careless about it.",fa:"renderer نقطه‌گذاری را مرتب می‌کند تا نویسنده‌های قالب لازم نباشد نگرانش باشند."}}]},{id:"designer",group:"templates",title:{en:"Designing, checking and publishing",fa:"طراحی، بررسی و انتشار"},files:["src/ClinicReport.Api/Endpoints/TemplateEndpoints.cs","src/ClinicReport.Api/Domain/TemplateValidator.cs","src/ClinicReport.Api/Data/Seeding.cs","web/src/pages/TemplateDesigner.tsx"],en:[{id:"endpoints",h:"Endpoints",p:["Reading the list is for anyone signed in (designers see every template; others only the active, published ones of their services). Changing anything needs `templates.design`."],data:{kind:"endpoints",only:["Templates"]}},{id:"versions",h:"A draft, then a frozen version",p:["Editing happens on one draft version. Publishing checks it, freezes it and makes it the version new reports start on; a report keeps the version it was started on, so changing a template never rewrites an old report. The key stays the same for good, since orders and exports refer to it."],examples:["publish","key"]},{id:"validator",h:"What the validator catches",p:["Ids in the right shape and unique across the template, options only where they belong, formulas that parse and use only number fields or `height`, `weight`, `age`, no formula that ends up depending on itself, `showIf` values that are options of the field they name, placeholders limited to `{label}`, `{value}`, `{unit}`, `{values}`. A draft may be saved with problems (they come back to the designer); it cannot be published with them."],examples:["placeholders","cycles"]},{id:"bundled",h:"Bundled templates",p:["`templates/*.json` are imported at start as published version 1 when their key is not in the database yet. One that does not validate is skipped and logged, not half-imported."],examples:["seed"]},{id:"fees",h:"What OHIP pays",p:["A template can carry the exam's OHIP technical and professional fees, in dollars and cents up to 10,000. Connected, they are what the accounting receives for each signed report; a template without fees sends nothing."],examples:["fees"]}],fa:[{id:"endpoints",h:"endpointها",p:["خواندن فهرست برای هر کسی است که وارد شده (designerها همه‌ی قالب‌ها را می‌بینند؛ بقیه فقط قالب‌های فعال و منتشرشده‌ی سرویس‌های خودشان را). هر تغییری `templates.design` لازم دارد."],data:{kind:"endpoints",only:["Templates"]}},{id:"versions",h:"یک پیش‌نویس، بعد نسخه‌ی یخ‌زده",p:["ویرایش روی یک نسخه‌ی پیش‌نویس انجام می‌شود. انتشار آن را چک می‌کند، یخ می‌زند و نسخه‌ای می‌کند که گزارش‌های تازه رویش شروع می‌شوند؛ هر گزارش نسخه‌ای را که رویش شروع شده نگه می‌دارد، پس تغییر قالب هیچ‌وقت گزارش قدیمی را بازنویسی نمی‌کند. key برای همیشه ثابت می‌ماند، چون درخواست‌ها و exportها به آن اشاره می‌کنند."],examples:["publish","key"]},{id:"validator",h:"validator چه چیزهایی را می‌گیرد",p:["idهای با شکل درست و یکتا در کل قالب، گزینه فقط جایی که باید، فرمول‌هایی که parse می‌شوند و فقط از فیلدهای عددی یا `height`، `weight`، `age` استفاده می‌کنند، هیچ فرمولی که آخرش به خودش وابسته شود، مقدارهای `showIf` که گزینه‌ی فیلدی باشند که نام می‌برند، جای‌نگه‌دارها فقط `{label}`، `{value}`، `{unit}`، `{values}`. پیش‌نویس با مشکل هم ذخیره می‌شود (مشکل‌ها به designer برمی‌گردند)؛ با مشکل منتشر نمی‌شود."],examples:["placeholders","cycles"]},{id:"bundled",h:"قالب‌های همراه",p:["`templates/*.json` موقع بالا آمدن، اگر key‌شان هنوز در دیتابیس نباشد، به‌عنوان نسخه‌ی منتشرشده‌ی 1 import می‌شوند. قالبی که از validator رد نشود کنار گذاشته و log می‌شود، نه نیمه‌کاره import."],examples:["seed"]},{id:"fees",h:"OHIP چقدر می‌پردازد",p:["قالب می‌تواند دستمزد فنی و حرفه‌ای OHIP آن معاینه را داشته باشد، به دلار و سنت تا 10,000. در حالت متصل، همین‌هاست که حسابداری برای هر گزارش امضاشده دریافت می‌کند؛ قالب بدون دستمزد چیزی نمی‌فرستد."],examples:["fees"]}],examples:{publish:{title:{en:"Publishing: check, then freeze",fa:"انتشار: چک، بعد یخ زدن"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/TemplateEndpoints.cs",from:'admin.MapPost("/{id:int}/publish"',lines:19},key:{title:{en:"The key never changes",fa:"key هیچ‌وقت عوض نمی‌شود"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/TemplateEndpoints.cs",from:"if (def!.Key != t.Key)",lines:2},placeholders:{title:{en:"Only known placeholders",fa:"فقط جای‌نگه‌دارهای شناخته‌شده"},lang:"csharp",file:"src/ClinicReport.Api/Domain/TemplateValidator.cs",from:"private static void CheckPlaceholders(string? phrase, string where, List<string> errors)",lines:8},cycles:{title:{en:"Formulas that depend on each other in a loop",fa:"فرمول‌هایی که دوری به هم وابسته‌اند"},lang:"csharp",file:"src/ClinicReport.Api/Domain/TemplateValidator.cs",from:"var state = new Dictionary<string, int>(); // 1 = visiting, 2 = done",to:"computed formulas refer to each other in a loop"},seed:{title:{en:"Importing the bundled templates",fa:"import قالب‌های همراه"},lang:"csharp",file:"src/ClinicReport.Api/Data/Seeding.cs",from:'foreach (var path in Directory.GetFiles(directory, "*.json").Order())',lines:22},fees:{title:{en:"Dollars and cents, or none",fa:"دلار و سنت، یا هیچ"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/TemplateEndpoints.cs",from:"static bool Bad(decimal? v)",lines:3}},quiz:[{q:{en:"A template is published again with a change. What happens to a report started on the old version?",fa:"یک قالب با تغییری دوباره منتشر می‌شود. گزارشی که روی نسخه‌ی قبلی شروع شده چه می‌شود؟"},options:{en:["It keeps the version it was started on","It moves to the new version","It is closed"],fa:["نسخه‌ای را که با آن شروع شده نگه می‌دارد","به نسخه‌ی تازه منتقل می‌شود","بسته می‌شود"]},answer:0,why:{en:"Published versions are frozen, so changing a template never rewrites an old report.",fa:"نسخه‌های منتشرشده یخ زده‌اند، پس تغییر قالب هیچ‌وقت گزارش قدیمی را بازنویسی نمی‌کند."}},{q:{en:"A draft has a formula that depends on itself through another field. What can the designer do with it?",fa:"یک پیش‌نویس فرمولی دارد که از طریق فیلد دیگری به خودش وابسته است. طراح با آن چه می‌تواند بکند؟"},options:{en:["Publish it; the cycle is broken at run time","Nothing: the draft cannot even be saved","Save it and see the problem, but not publish it"],fa:["منتشرش کند؛ چرخه موقع اجرا شکسته می‌شود","هیچ: پیش‌نویس حتی ذخیره هم نمی‌شود","ذخیره‌اش کند و مشکل را ببیند، ولی منتشرش نکند"]},answer:2,why:{en:"The validator's problems come back to the designer on save; publishing requires none.",fa:"مشکل‌های validator موقع ذخیره به طراح برمی‌گردند؛ انتشار هیچ مشکلی را نمی‌پذیرد."}},{q:{en:"Why can a template's key never change?",fa:"چرا کلید یک قالب هیچ‌وقت عوض نمی‌شود؟"},options:{en:["SQLite cannot rename keys","Orders and exports refer to it","It is the file name on disk"],fa:["SQLite نمی‌تواند کلیدها را تغییر نام دهد","درخواست‌ها و خروجی‌ها به آن ارجاع می‌دهند","اسم فایل روی دیسک است"]},answer:1,why:{en:"ClinicHub codes an exam with the template key, so a changed key would break incoming orders.",fa:"ClinicHub هر معاینه را با کلید قالب کد می‌کند، پس کلید عوض‌شده درخواست‌های ورودی را خراب می‌کرد."}}]},{id:"report-service",group:"reports",title:{en:"Every change through one service",fa:"هر تغییر از یک سرویس"},files:["src/ClinicReport.Api/Endpoints/ReportEndpoints.cs","src/ClinicReport.Api/Reports/ReportService.cs","src/ClinicReport.Api/Program.cs"],en:[{id:"endpoints",h:"Endpoints",p:["Every `/{id}` route goes through two filters: the report must belong to a service the user may work on (otherwise 404, as if it did not exist), and a restricted one must have been opened by this user (see Restricted items)."],data:{kind:"endpoints",only:["Reports"]},examples:["filter"]},{id:"one",h:"One place for the rules",p:["The endpoints only pass the request to `ReportService`. Every change, whatever it is (answers, an *All normal* preset, the header, the conclusion, the signature), runs the same steps: load, refuse if signed, apply, record each changed field with who and when in `Changes`, raise the revision, save, broadcast to everyone who has the report open."]},{id:"concurrency",h:"Two people, no lost answers",p:["`Revision` is a concurrency token: a save whose revision someone else has already raised fails. The service then forgets what it loaded and applies the same change to the newer report, up to five times. Two people typing in different fields never overwrite each other, because each save only sets the fields it carries."],examples:["mutate","token"]},{id:"normalize",h:"Answers must fit the template",p:["A choice must be one of its options, a multi a list of them (kept in template order, so the sentence reads the same however it was clicked), a number a number below a million, a text at most 4,000 characters; a calculated field cannot be typed at all. Breaking a rule throws `ReportRuleException`, which `Program.cs` turns into a ProblemDetails with its status."],examples:["multi","handler"]},{id:"sign",h:"Signing freezes it",p:["Only `reports.sign` signs. Required fields and a conclusion are checked first (422); then the rendered text is saved as it is (`SignedSnapshotJson`), so the signed report reads the same even if the code that renders it changes later. After that only addenda can be added, each one also logged."],examples:["sign","addendum"]},{id:"tables",h:"Tables",data:{kind:"tables",only:["Reports","Changes","Addenda"]}}],fa:[{id:"endpoints",h:"endpointها",p:["هر route با `/{id}` از دو filter رد می‌شود: گزارش باید مال سرویسی باشد که کاربر اجازه‌ی کار رویش را دارد (وگرنه 404، انگار وجود ندارد)، و گزارش محدودشده باید قبلاً به دست همین کاربر باز شده باشد (بخش موارد محدودشده را ببینید)."],data:{kind:"endpoints",only:["Reports"]},examples:["filter"]},{id:"one",h:"یک جا برای قانون‌ها",p:["endpointها فقط درخواست را به `ReportService` می‌دهند. هر تغییری، هر چه باشد (جواب‌ها، preset *All normal*، سربرگ، نتیجه‌گیری، امضا)، همان قدم‌ها را می‌رود: بارگذاری، رد اگر امضا شده، اعمال، ثبت هر فیلد عوض‌شده با چه کسی و کی در `Changes`، بالا بردن revision، ذخیره، و پخش برای همه‌ی کسانی که گزارش را باز کرده‌اند."]},{id:"concurrency",h:"دو نفر، بدون جواب گم‌شده",p:["`Revision` یک concurrency token است: ذخیره‌ای که revisionش را کس دیگری قبلاً بالا برده شکست می‌خورد. سرویس آن‌وقت چیزی را که بارگذاری کرده فراموش می‌کند و همان تغییر را روی گزارش تازه‌تر اعمال می‌کند، تا پنج بار. دو نفری که در فیلدهای مختلف تایپ می‌کنند هیچ‌وقت روی هم نمی‌نویسند، چون هر ذخیره فقط فیلدهایی را که همراه دارد تنظیم می‌کند."],examples:["mutate","token"]},{id:"normalize",h:"جواب‌ها باید با قالب جور باشند",p:["choice باید یکی از گزینه‌هایش باشد، multi فهرستی از آن‌ها (به ترتیب قالب نگه داشته می‌شود، پس جمله هر طور کلیک شده باشد یکی است)، number عددی کمتر از یک میلیون، text حداکثر 4,000 کاراکتر؛ فیلد محاسبه‌ای اصلاً تایپ نمی‌شود. شکستن یک قانون `ReportRuleException` می‌اندازد، که `Program.cs` آن را به ProblemDetails با status خودش تبدیل می‌کند."],examples:["multi","handler"]},{id:"sign",h:"امضا آن را یخ می‌زند",p:["فقط `reports.sign` امضا می‌کند. اول فیلدهای اجباری و نتیجه‌گیری چک می‌شوند (422)؛ بعد متن render‌شده همان‌طور که هست ذخیره می‌شود (`SignedSnapshotJson`)، پس گزارش امضاشده حتی اگر کدی که آن را render می‌کند بعداً عوض شود همان‌طور خوانده می‌شود. بعد از آن فقط addendum می‌شود اضافه کرد، که هر کدام هم ثبت می‌شود."],examples:["sign","addendum"]},{id:"tables",h:"جدول‌ها",data:{kind:"tables",only:["Reports","Changes","Addenda"]}}],examples:{filter:{title:{en:"The filtered group",fa:"گروه filter‌دار"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/ReportEndpoints.cs",from:"// Every /{id} route: the report must exist",lines:3},mutate:{title:{en:"Save, or start over from their version",fa:"ذخیره، یا از نسخه‌ی آن‌ها از نو"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportService.cs",from:"for (var attempt = 1; ; attempt++)",to:"continue;"},token:{title:{en:"The concurrency token",fa:"concurrency token"},lang:"csharp",file:"src/ClinicReport.Api/Data/ClinicReportDbContext.cs",from:"e.Property(r => r.Revision).IsConcurrencyToken();",lines:1},multi:{title:{en:"A multi answer, in template order",fa:"جواب multi، به ترتیب قالب"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportService.cs",from:"case FieldTypes.Multi:",lines:9},handler:{title:{en:"A broken rule becomes ProblemDetails",fa:"قانون شکسته ProblemDetails می‌شود"},lang:"csharp",file:"src/ClinicReport.Api/Program.cs",from:"internal sealed class ReportRuleHandler",lines:15},sign:{title:{en:"Before and at the signature",fa:"قبل از امضا و هنگام آن"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportService.cs",from:"if (rendered.MissingRequired.Count > 0)",lines:8},addendum:{title:{en:"Addenda only after signing",fa:"addendum فقط بعد از امضا"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportService.cs",from:"if (report.Status != ReportStatus.Final)",lines:2}},quiz:[{q:{en:"Two saves of the same report arrive together; one fails on the concurrency token. What does the service do?",fa:"دو ذخیره‌ی یک گزارش با هم می‌رسند؛ یکی روی concurrency token شکست می‌خورد. سرویس چه می‌کند؟"},options:{en:["Returns 409 to the user","Overwrites the newer report","Reloads and applies the same change to the newer report, up to five times"],fa:["به کاربر 409 برمی‌گرداند","گزارش جدیدتر را بازنویسی می‌کند","دوباره بارگذاری می‌کند و همان تغییر را روی گزارش جدیدتر اعمال می‌کند، تا پنج بار"]},answer:2,why:{en:"Each save sets only the fields it carries, so applying it again on the newer revision loses nothing.",fa:"هر ذخیره فقط فیلدهایی را که دارد می‌گذارد، پس اعمال دوباره‌اش روی revision جدیدتر چیزی را گم نمی‌کند."}},{q:{en:"A user opens a report of a service they may not work on. What do they get?",fa:"کاربری گزارشِ سرویسی را باز می‌کند که اجازه‌ی کار روی آن را ندارد. چه می‌گیرد؟"},options:{en:["404, as if it did not exist","403 with the reason","The report, read-only"],fa:["404، انگار وجود ندارد","403 با دلیل","گزارش، فقط‌خواندنی"]},answer:0,why:{en:"The `/{id}` filter answers 404 so the existence of other services' reports is not revealed.",fa:"filter‌ی `/{id}` جواب 404 می‌دهد تا وجود گزارش‌های سرویس‌های دیگر لو نرود."}},{q:{en:"Why is the rendered text saved at signing (`SignedSnapshotJson`)?",fa:"چرا متن رندرشده موقع امضا ذخیره می‌شود (`SignedSnapshotJson`)؟"},options:{en:["To make the worklist faster","So the signed report reads the same even if the rendering code changes later","Because the answers are deleted after signing"],fa:["تا worklist سریع‌تر شود","تا گزارش امضاشده حتی اگر کد رندر بعداً عوض شود همان‌طور خوانده شود","چون جواب‌ها بعد از امضا حذف می‌شوند"]},answer:1,why:{en:"What the physician signed must not change; afterwards only addenda can be added.",fa:"چیزی که پزشک امضا کرده نباید عوض شود؛ بعد از آن فقط addendum اضافه می‌شود."}}]},{id:"live",group:"reports",title:{en:"Live co-editing (SignalR)",fa:"ویرایش هم‌زمان زنده (SignalR)"},files:["src/ClinicReport.Api/Reports/ReportHub.cs","web/src/live.ts","web/src/pages/ReportEditor.tsx"],en:[{id:"split",h:"Changes over REST, news over the hub",p:["The typist and the physician work on the same report during the exam. Changes still go through the REST API, so they are checked and logged in one place; the SignalR hub only carries who is in the report, which field each one is in, and the new report after every save."],examples:["hub","broadcast"]},{id:"presence",h:"Presence, in memory",p:["Joining checks the report exists and belongs to one of the user's services, then adds the connection to the report's group. Who is where is kept in memory: one API instance serves a clinic. Several instances would need a SignalR backplane and a shared store."],examples:["join"]},{id:"client",h:"The page ignores its own echo",p:["Every tab sends a random `X-Client-Id`; the broadcast carries the id of the tab that made the change, and that tab skips it. After a reconnection the page joins again and reloads the report, since changes may have been missed while offline."],examples:["receive","reconnect"]},{id:"typing",h:"Typing is never overwritten",p:["What is typed but not yet sent is kept apart and wins over whatever arrives from the server until it has been sent; an older answer overtaken by a newer revision is dropped. A click saves at once, typing after half a second's pause."],examples:["accept","debounce"]}],fa:[{id:"split",h:"تغییرها از REST، خبرها از hub",p:["تایپیست و پزشک در طول معاینه روی یک گزارش کار می‌کنند. تغییرها باز هم از REST API می‌روند، پس در یک جا چک و ثبت می‌شوند؛ hub SignalR فقط این را می‌برد که چه کسی در گزارش است، هر کس در کدام فیلد است، و گزارش تازه بعد از هر ذخیره."],examples:["hub","broadcast"]},{id:"presence",h:"حضور، در حافظه",p:["پیوستن چک می‌کند که گزارش وجود دارد و مال یکی از سرویس‌های کاربر است، بعد connection را به گروه گزارش اضافه می‌کند. این‌که چه کسی کجاست در حافظه نگه داشته می‌شود: یک نمونه‌ی API به یک کلینیک خدمت می‌کند. چند نمونه یک SignalR backplane و یک store مشترک لازم دارد."],examples:["join"]},{id:"client",h:"صفحه پژواک خودش را نادیده می‌گیرد",p:["هر tab یک `X-Client-Id` تصادفی می‌فرستد؛ پخش، id تبی را که تغییر را داده همراه دارد و همان tab از آن می‌گذرد. بعد از وصل شدن دوباره، صفحه دوباره می‌پیوندد و گزارش را از نو بار می‌کند، چون ممکن است در قطعی تغییرهایی از دست رفته باشد."],examples:["receive","reconnect"]},{id:"typing",h:"تایپ هیچ‌وقت رونویسی نمی‌شود",p:["چیزی که تایپ شده ولی هنوز فرستاده نشده جدا نگه داشته می‌شود و تا فرستاده نشده بر هر چه از سرور می‌آید غلبه می‌کند؛ جواب قدیمی‌تری که revision تازه‌تری از آن جلو زده دور ریخته می‌شود. کلیک همان لحظه ذخیره می‌شود، تایپ بعد از نیم ثانیه مکث."],examples:["accept","debounce"]}],examples:{hub:{title:{en:"The hub, for readers of reports",fa:"hub، برای خواننده‌های گزارش"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportHub.cs",from:"/// Live channel for an open report.",lines:5},broadcast:{title:{en:"After every save",fa:"بعد از هر ذخیره"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportService.cs",from:"private Task BroadcastAsync(ReportDto dto, string? clientId, CancellationToken ct) =>",lines:2},join:{title:{en:"Joining a report",fa:"پیوستن به یک گزارش"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportHub.cs",from:"public async Task JoinReport(int reportId)",lines:15},receive:{title:{en:"Skipping its own change",fa:"رد شدن از تغییر خودش"},lang:"typescript",file:"web/src/live.ts",from:"conn.on('reportChanged'",lines:4},reconnect:{title:{en:"Back online: join and reload",fa:"برگشت به خط: پیوستن و بارگذاری دوباره"},lang:"typescript",file:"web/src/live.ts",from:"conn.onreconnected(async () => {",lines:5},accept:{title:{en:"Taking the server's report, keeping local typing",fa:"گرفتن گزارش سرور، نگه داشتن تایپ محلی"},lang:"typescript",file:"web/src/pages/ReportEditor.tsx",from:"/** Takes a report from the server",lines:14},debounce:{title:{en:"Clicks now, typing after a pause",fa:"کلیک فوری، تایپ بعد از مکث"},lang:"typescript",file:"web/src/pages/ReportEditor.tsx",from:"// Clicks save at once; typing waits for a pause.",lines:2}},quiz:[{q:{en:"Why do changes go through the REST API and not through the SignalR hub?",fa:"چرا تغییرها از REST API می‌گذرند و نه از hub‌ی SignalR؟"},options:{en:["So they are checked and logged in one place","SignalR cannot carry JSON","The hub is read-only by design of SignalR"],fa:["تا در یک جا چک و ثبت شوند","SignalR نمی‌تواند JSON ببرد","hub به‌خاطر طراحی SignalR فقط‌خواندنی است"]},answer:0,why:{en:"The hub only carries presence, focus and the new report after each save.",fa:"hub فقط حضور، فیلد فعلی هر نفر و گزارش تازه بعد از هر ذخیره را می‌برد."}},{q:{en:"A tab receives the broadcast of its own save. What does it do?",fa:"یک tab پخش ذخیره‌ی خودش را دریافت می‌کند. چه می‌کند؟"},options:{en:["Applies it again","Skips it: the broadcast carries the `X-Client-Id` of the tab that made the change","Reloads the page"],fa:["دوباره اعمالش می‌کند","ردش می‌کند: پخش، `X-Client-Id` tabی را که تغییر را داده دارد","صفحه را دوباره بارگذاری می‌کند"]},answer:1,why:{en:"Each tab sends a random client id; ignoring its own echo avoids redrawing over what it is typing.",fa:"هر tab یک client id تصادفی می‌فرستد؛ نادیده گرفتن پژواک خودش از رسم دوباره روی چیزی که در حال تایپ است جلوگیری می‌کند."}},{q:{en:"Why could ClinicReport not simply run as three API instances for one clinic?",fa:"چرا ClinicReport نمی‌تواند به‌سادگی با سه نمونه‌ی API برای یک کلینیک اجرا شود؟"},options:{en:["SQLite refuses three connections","The cookie would be different on each","Presence is kept in memory; several instances would need a backplane and a shared store"],fa:["SQLite سه اتصال را رد می‌کند","کوکی در هر کدام فرق می‌کرد","حضور در حافظه نگه داشته می‌شود؛ چند نمونه backplane و یک store مشترک لازم داشتند"]},answer:2,why:{en:"One API instance serves a clinic; that is what keeping presence in memory assumes.",fa:"یک نمونه‌ی API یک کلینیک را سرویس می‌دهد؛ نگه داشتن حضور در حافظه همین را فرض می‌کند."}}]},{id:"patients",group:"reports",title:{en:"Patients",fa:"بیمارها"},files:["src/ClinicReport.Api/Endpoints/PatientEndpoints.cs"],en:[{id:"endpoints",h:"A minimal register",p:["Just enough for the app to work on its own: search by MRN or name, add, correct. Reading needs any of view reports, start reports or manage patients (the `patients.read` policy); changing needs `patients.manage`. Connected, patients arrive with ClinicHub's orders instead, and ClinicHub's demographics win.",`The search takes an exact MRN or the start of a last or first name and returns at most 50 rows, sorted by name. Last names use SQLite's NOCASE collation, so "smith" finds Smith without anything in the query.`],examples:["read","plausible"],data:{kind:"endpoints",only:["Patients"]}},{id:"checks",h:"What a patient must have",p:["Adding and correcting share one check: an MRN of 1 to 32 characters that no other patient has, first and last names up to 64 characters, a date of birth neither in the future nor more than 125 years back, and a sex of `M`, `F`, `X` or `U`. Every problem is collected and returned together as one validation problem, field by field, so the form can mark them all at once."]},{id:"hub",h:"Connected, ClinicHub's details win",p:["Every order from ClinicHub carries the patient. ClinicReport finds them by MRN, or adds them, and then overwrites name, date of birth and sex with ClinicHub's, since ClinicHub's register is the source of truth. A correction made at the clinic reaches the next report without anyone typing it twice."],examples:["demographics"]},{id:"merge",h:"Two records become one",p:["When ClinicHub merges two charts it sends the merged MRN with a link to the surviving one. Known only by the old MRN here, the patient takes the new one; known by both, the old one's reports, orders and log entries move to the survivor and the old record is removed.","Known by both MRNs, the move is three bulk updates (`ExecuteUpdateAsync`) on reports, orders and security events, then the old record is removed, all before one `SaveChanges`. Nothing that pointed at the old chart is lost, including who opened its reports. A patient never seen here is simply answered 200."],examples:["merge"]},{id:"table",h:"Table",data:{kind:"tables",only:["Patients"]}}],fa:[{id:"endpoints",h:"یک فهرست حداقلی",p:["فقط به اندازه‌ای که اپ خودش تنها کار کند: جست‌وجو با MRN یا اسم، اضافه کردن، اصلاح. خواندن یکی از مجوزهای دیدن گزارش، شروع گزارش یا مدیریت بیمار را لازم دارد (policy `patients.read`)؛ تغییر `patients.manage` را. در حالت متصل، بیمارها به‌جایش با درخواست‌های ClinicHub می‌آیند، و مشخصات ClinicHub برنده است.","جستجو یک MRN دقیق یا ابتدای نام خانوادگی یا نام را می‌گیرد و حداکثر ۵۰ ردیف مرتب‌شده بر اساس اسم برمی‌گرداند. نام خانوادگی collation‌ی NOCASE در SQLite را دارد، پس «smith» بدون هیچ کاری در کوئری Smith را پیدا می‌کند."],examples:["read","plausible"],data:{kind:"endpoints",only:["Patients"]}},{id:"checks",h:"یک بیمار چه چیزهایی باید داشته باشد",p:["اضافه کردن و اصلاح یک چک مشترک دارند: MRNی بین ۱ تا ۳۲ کاراکتر که بیمار دیگری نداشته باشد، نام و نام خانوادگی تا ۶۴ کاراکتر، تاریخ تولدی که نه در آینده باشد و نه بیش از ۱۲۵ سال پیش، و جنس `M`، `F`، `X` یا `U`. همه‌ی مشکل‌ها جمع می‌شوند و با هم به شکل یک validation problem، فیلد به فیلد، برمی‌گردند تا فرم بتواند همه را یک‌جا علامت بزند."]},{id:"hub",h:"در حالت متصل، اطلاعات ClinicHub برنده است",p:["هر درخواست از ClinicHub بیمار را با خودش دارد. ClinicReport او را با MRN پیدا می‌کند، یا اضافه‌اش می‌کند، و بعد نام، تاریخ تولد و جنس را با اطلاعات ClinicHub بازنویسی می‌کند، چون دفتر ثبت ClinicHub منبع حقیقت است. اصلاحی که در کلینیک انجام شده بدون این‌که کسی دو بار تایپش کند به گزارش بعدی می‌رسد."],examples:["demographics"]},{id:"merge",h:"دو پرونده یکی می‌شوند",p:["وقتی ClinicHub دو پرونده را ادغام می‌کند، MRN ادغام‌شده را با لینکی به پرونده‌ی ماندگار می‌فرستد. اگر این‌جا بیمار فقط با MRN قدیمی شناخته شده باشد، MRN تازه را می‌گیرد؛ اگر با هر دو، گزارش‌ها، درخواست‌ها و ردیف‌های log قدیمی به ماندگار منتقل و پرونده‌ی قدیمی حذف می‌شود.","وقتی هر دو MRN شناخته شده‌اند، انتقال سه به‌روزرسانی دسته‌ای (`ExecuteUpdateAsync`) روی گزارش‌ها، درخواست‌ها و رویدادهای امنیتی است و بعد پرونده‌ی قدیمی حذف می‌شود، همه قبل از یک `SaveChanges`. هیچ چیزی که به پرونده‌ی قدیمی اشاره می‌کرد گم نمی‌شود، حتی این‌که چه کسی گزارش‌هایش را باز کرده. به بیماری که این‌جا هرگز دیده نشده فقط جواب 200 داده می‌شود."],examples:["merge"]},{id:"table",h:"جدول",data:{kind:"tables",only:["Patients"]}}],examples:{read:{title:{en:"Reading patients: any of three permissions",fa:"خواندن بیمارها: یکی از سه مجوز"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"auth.AddPolicy(PatientsRead",lines:2},plausible:{title:{en:"A plausible date of birth",fa:"تاریخ تولد معقول"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/PatientEndpoints.cs",from:"var today = DateOnly.FromDateTime(clock.GetLocalNow().DateTime);",lines:4},merge:{title:{en:"Moving to the surviving record",fa:"انتقال به پرونده‌ی ماندگار"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"var old = await db.Patients.SingleOrDefaultAsync(p => p.Mrn == merged);",lines:14},demographics:{title:{en:"ClinicHub's register is the source of truth",fa:"دفتر ثبت ClinicHub منبع حقیقت است"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"var local = await db.Patients.SingleOrDefaultAsync(p => p.Mrn == mrn)",lines:7}},quiz:[{q:{en:"Someone adds a patient with an MRN another patient already has. What happens?",fa:"کسی بیماری با MRNی اضافه می‌کند که بیمار دیگری از قبل دارد. چه می‌شود؟"},options:{en:["The two records are merged","A validation problem on `mrn`: another patient has it","The new patient gets a suffix"],fa:["دو پرونده ادغام می‌شوند","یک validation problem روی `mrn`: بیمار دیگری آن را دارد","بیمار تازه یک پسوند می‌گیرد"]},answer:1,why:{en:"The MRN is unique in the table and checked before saving, for adding and correcting alike.",fa:"MRN در جدول یکتاست و قبل از ذخیره چک می‌شود، هم برای اضافه کردن و هم برای اصلاح."}},{q:{en:"ClinicHub merges two charts that are both known here. What happens to the old one's reports?",fa:"ClinicHub دو پرونده را ادغام می‌کند که هر دو این‌جا شناخته شده‌اند. گزارش‌های پرونده‌ی قدیمی چه می‌شوند؟"},options:{en:["They move to the survivor, with its orders and log entries, and the old record is removed","They are deleted with the old record","They stay on the old record, marked inactive"],fa:["با درخواست‌ها و ورودی‌های لاگش به پرونده‌ی باقی‌مانده منتقل می‌شوند و پرونده‌ی قدیمی حذف می‌شود","با پرونده‌ی قدیمی حذف می‌شوند","روی پرونده‌ی قدیمی، با علامت غیرفعال، می‌مانند"]},answer:0,why:{en:"Three bulk updates repoint everything at the surviving patient before the old one goes.",fa:"سه به‌روزرسانی دسته‌ای همه‌چیز را قبل از رفتن پرونده‌ی قدیمی به بیمار باقی‌مانده اشاره می‌دهند."}},{q:{en:"Connected, a receptionist here corrects a patient's last name, then a new order arrives. Which name does the patient have?",fa:"در حالت متصل، پذیرش این‌جا نام خانوادگی بیماری را اصلاح می‌کند و بعد درخواست تازه‌ای می‌رسد. بیمار چه نامی دارد؟"},options:{en:["The one corrected here","Both, joined","ClinicHub's, from the order"],fa:["همانی که این‌جا اصلاح شده","هر دو، کنار هم","نام ClinicHub، از درخواست"]},answer:2,why:{en:"Every order overwrites the demographics with ClinicHub's, which is the source of truth.",fa:"هر درخواست اطلاعات هویتی را با اطلاعات ClinicHub، که منبع حقیقت است، بازنویسی می‌کند."}}]},{id:"accounts",group:"security",title:{en:"Standalone accounts and sign-in",fa:"حساب‌های مستقل و ورود"},files:["src/ClinicReport.Api/Endpoints/AuthEndpoints.cs","src/ClinicReport.Api/Auth/AuthSetup.cs","src/ClinicReport.Api/Data/Seeding.cs"],en:[{id:"endpoints",h:"Endpoints",p:["Standalone, ClinicReport has its own accounts. Connected to ClinicHub, the password and two-factor endpoints answer 409 (“managed in ClinicHub”) and `/sso/*` take over."],data:{kind:"endpoints",only:["Auth"]}},{id:"cookie",h:"A cookie that holds almost nothing",p:["The cookie (HttpOnly, SameSite=Strict, 12 hours sliding) holds the user id and a security stamp. Roles, permissions and services are read from the database on every request, so an administrator's change applies at once; a new stamp (password reset, deactivation, *sign out everywhere*) ends every other session. An API answers 401 and 403; it never redirects to a login page."]},{id:"guess",h:"Against guessing",p:["Five wrong passwords lock the account for 15 minutes; sign-in is limited to 10 attempts a minute per IP address. The password is hashed even for a user name that does not exist, so the time taken does not reveal which names are real."],examples:["lockout","timing","rate"]},{id:"first",h:"The first sign-in",p:["A brand-new database gets one `admin` with a generated password printed in the log (or `Bootstrap:AdminPassword`). That account, and everyone an administrator adds, must choose their own password first: until then the only endpoints that answer are `/api/auth` and `/api/settings`. A password needs 10 characters, four different ones, and not the user name."],examples:["bootstrap","pending","password"]},{id:"table",h:"Table",data:{kind:"tables",only:["Users"]}}],fa:[{id:"endpoints",h:"endpointها",p:["در حالت مستقل، ClinicReport حساب‌های خودش را دارد. وقتی به ClinicHub وصل است، endpointهای رمز و دومرحله‌ای 409 («در ClinicHub مدیریت می‌شود») می‌دهند و `/sso/*` کار را به دست می‌گیرند."],data:{kind:"endpoints",only:["Auth"]}},{id:"cookie",h:"کوکی‌ای که تقریباً هیچ چیز ندارد",p:["کوکی (HttpOnly، SameSite=Strict، ۱۲ ساعت لغزان) id کاربر و یک security stamp را دارد. نقش‌ها، مجوزها و سرویس‌ها در هر درخواست از دیتابیس خوانده می‌شوند، پس تغییری که admin می‌دهد همان لحظه اعمال می‌شود؛ stamp تازه (ریست رمز، غیرفعال کردن، *خروج از همه جا*) همه‌ی session‌های دیگر را تمام می‌کند. API جواب 401 و 403 می‌دهد؛ هیچ‌وقت به صفحه‌ی ورود redirect نمی‌کند."]},{id:"guess",h:"در برابر حدس زدن",p:["پنج رمز غلط حساب را ۱۵ دقیقه قفل می‌کند؛ ورود به ۱۰ تلاش در دقیقه برای هر IP محدود است. رمز حتی برای نام کاربری‌ای که وجود ندارد هم hash می‌شود، پس زمانی که طول می‌کشد لو نمی‌دهد کدام نام‌ها واقعی‌اند."],examples:["lockout","timing","rate"]},{id:"first",h:"اولین ورود",p:["یک دیتابیس تازه یک `admin` می‌گیرد با رمزی ساخته‌شده که در log چاپ می‌شود (یا `Bootstrap:AdminPassword`). آن حساب، و هر کسی که admin اضافه می‌کند، اول باید رمز خودش را انتخاب کند: تا آن موقع تنها endpointهایی که جواب می‌دهند `/api/auth` و `/api/settings` هستند. رمز ۱۰ کاراکتر می‌خواهد، چهار کاراکتر متفاوت، و نه نام کاربری."],examples:["bootstrap","pending","password"]},{id:"table",h:"جدول",data:{kind:"tables",only:["Users"]}}],examples:{lockout:{title:{en:"A locked account",fa:"حساب قفل‌شده"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/AuthEndpoints.cs",from:"if (user?.LockoutEndUtc is { } until",lines:6},timing:{title:{en:"The same work for an unknown name",fa:"همان کار برای نام ناشناخته"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/AuthEndpoints.cs",from:"// Hash even when the user does not exist",lines:4},rate:{title:{en:"Sign-ins per minute per address",fa:"ورود در دقیقه برای هر آدرس"},lang:"csharp",file:"src/ClinicReport.Api/Program.cs",from:"var loginsPerMinute",lines:8},bootstrap:{title:{en:"The first admin",fa:"اولین admin"},lang:"csharp",file:"src/ClinicReport.Api/Data/Seeding.cs",from:'var password = config["Bootstrap:AdminPassword"];',lines:4},pending:{title:{en:"Nothing else until the password is chosen",fa:"هیچ چیز دیگر تا رمز انتخاب شود"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"public static IApplicationBuilder UsePendingActionGate(this IApplicationBuilder app) => app.Use(async (ctx, next) =>",lines:13},password:{title:{en:"What a password needs",fa:"رمز چه لازم دارد"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/UserEndpoints.cs",from:"public static string? PasswordProblem(string? password, string? userName = null) =>",lines:6}},quiz:[{q:{en:"An administrator removes a role from a user who is signed in. When does it take effect?",fa:"مدیری نقشی را از کاربری که وارد شده برمی‌دارد. کی اثر می‌کند؟"},options:{en:["At the user's next sign-in","On the next request: permissions are read from the database every time","After 12 hours, when the cookie expires"],fa:["در ورود بعدی کاربر","در درخواست بعدی: مجوزها هر بار از دیتابیس خوانده می‌شوند","بعد از ۱۲ ساعت، وقتی کوکی منقضی شود"]},answer:1,why:{en:"The cookie holds only the user id and a security stamp, so nothing stale is trusted.",fa:"کوکی فقط شناسه‌ی کاربر و یک security stamp دارد، پس به چیز کهنه‌ای اعتماد نمی‌شود."}},{q:{en:"Why is the password hashed even for a user name that does not exist?",fa:"چرا رمز حتی برای نام کاربری‌ای که وجود ندارد hash می‌شود؟"},options:{en:["So the response time does not reveal which names are real","To keep a record of failed attempts","Because the hasher needs warming up"],fa:["تا زمان جواب لو ندهد کدام نام‌ها واقعی‌اند","برای نگه داشتن سابقه‌ی تلاش‌های ناموفق","چون hasher باید گرم شود"]},answer:0,why:{en:"Skipping the hash for unknown names would make them answer measurably faster.",fa:"رد شدن از hash برای نام‌های ناشناخته باعث می‌شد آن‌ها به‌طور قابل اندازه‌گیری سریع‌تر جواب بگیرند."}},{q:{en:"A new user has not yet chosen their own password. What can they reach?",fa:"کاربر تازه‌ای هنوز رمز خودش را انتخاب نکرده. به چه چیزی دسترسی دارد؟"},options:{en:["Everything their roles allow","Read-only pages","Only `/api/auth` and `/api/settings`"],fa:["هر چیزی که نقش‌هایش اجازه می‌دهند","صفحه‌های فقط‌خواندنی","فقط `/api/auth` و `/api/settings`"]},answer:2,why:{en:"The pending-action gate answers every other endpoint until the password is changed.",fa:"دروازه‌ی کار معوق تا عوض شدن رمز به هر endpoint دیگری جواب رد می‌دهد."}}]},{id:"totp",group:"security",title:{en:"Two-factor sign-in (TOTP)",fa:"ورود دومرحله‌ای (TOTP)"},files:["src/ClinicReport.Api/Auth/Totp.cs","src/ClinicReport.Api/Endpoints/AuthEndpoints.cs","web/src/components/TwoFactorSetup.tsx"],en:[{id:"rfc",h:"RFC 6238, in 80 lines",p:["The codes any authenticator app shows: HMAC-SHA1 of the number of 30-second steps since 1970, cut to 6 digits. No library: a new secret is 20 random bytes in base32, and the `otpauth://` link the setup page turns into a QR code carries it."],examples:["code","uri"]},{id:"verify",h:"A code works once",p:["A code is accepted for the current step or one either side (a phone's clock is rarely exact), compared in constant time. The step it matched is saved, and steps at or before it are refused, so a code seen over someone's shoulder cannot be used again.","At sign-in the password is checked first. With two-factor on and no code, the answer is a 401 with `twoFactorRequired`, so the page asks for the code; a wrong or reused code is a failed sign-in like a wrong password, and counts towards the five that lock the account."],examples:["verify","login"]},{id:"secret",h:"The secret is encrypted",p:["The secret is stored encrypted with ASP.NET Data Protection (the same keys as the cookie, in `/data/keys` in the container). Turning two-factor off needs the password, and is refused when one of the user's roles requires it."],examples:["protect"]},{id:"setup",h:"Turned on only after one good code",p:["Setup makes a new secret, stores it encrypted and returns it with the `otpauth://` link, but two-factor is not on yet. Only `enable` with a correct code turns it on, which proves the phone really holds the secret; otherwise a scan that failed would lock the user out at their next sign-in. Setup is refused while two-factor is on: to move to a new phone, turn it off first. A role that requires two-factor sends its users to this setup before any other page."],examples:["enable"]}],fa:[{id:"rfc",h:"RFC 6238، در ۸۰ خط",p:["همان کدهایی که هر اپ authenticator نشان می‌دهد: HMAC-SHA1 تعداد گام‌های ۳۰ ثانیه‌ای از ۱۹۷۰، بریده به ۶ رقم. بدون کتابخانه: secret تازه ۲۰ بایت تصادفی در base32 است، و لینک `otpauth://` که صفحه‌ی راه‌اندازی آن را QR code می‌کند آن را با خودش دارد."],examples:["code","uri"]},{id:"verify",h:"یک کد یک بار کار می‌کند",p:["کد برای گام فعلی یا یک گام این‌ور و آن‌ورش قبول می‌شود (ساعت گوشی کم پیش می‌آید دقیق باشد)، با مقایسه‌ی constant-time. گامی که جور شده ذخیره می‌شود، و گام‌های تا آن رد می‌شوند، پس کدی که کسی از پشت شانه دیده دوباره به کار نمی‌آید.","در ورود، اول رمز چک می‌شود. اگر ورود دومرحله‌ای روشن باشد و کدی نیامده باشد، جواب یک 401 با `twoFactorRequired` است تا صفحه کد را بخواهد؛ کد اشتباه یا تکراری مثل رمز اشتباه یک ورود ناموفق است و جزو آن پنج تایی حساب می‌شود که حساب را قفل می‌کنند."],examples:["verify","login"]},{id:"secret",h:"secret رمز شده است",p:["secret با ASP.NET Data Protection رمزشده ذخیره می‌شود (همان کلیدهای کوکی، در container در `/data/keys`). خاموش کردن دومرحله‌ای رمز عبور لازم دارد، و وقتی یکی از نقش‌های کاربر آن را اجباری کرده رد می‌شود."],examples:["protect"]},{id:"setup",h:"فقط بعد از یک کد درست روشن می‌شود",p:["setup یک secret تازه می‌سازد، آن را رمزشده ذخیره می‌کند و با لینک `otpauth://` برمی‌گرداند، ولی هنوز ورود دومرحله‌ای روشن نیست. فقط `enable` با یک کد درست روشنش می‌کند، که ثابت می‌کند گوشی واقعاً secret را دارد؛ وگرنه اسکنی که خراب شده کاربر را در ورود بعدی پشت در می‌گذاشت. تا وقتی ورود دومرحله‌ای روشن است setup رد می‌شود: برای رفتن به گوشی تازه اول باید خاموشش کرد. نقشی که ورود دومرحله‌ای را لازم می‌داند کاربرانش را قبل از هر صفحه‌ی دیگری به همین setup می‌فرستد."],examples:["enable"]}],examples:{code:{title:{en:"The code for one step",fa:"کد یک گام"},lang:"csharp",file:"src/ClinicReport.Api/Auth/Totp.cs",from:"public static string Code(string secret, long step)",lines:10},uri:{title:{en:"The link for the QR code",fa:"لینک QR code"},lang:"csharp",file:"src/ClinicReport.Api/Auth/Totp.cs",from:"public static string OtpAuthUri(string issuer, string account, string secret) =>",lines:3},verify:{title:{en:"One step either side, never twice",fa:"یک گام این‌ور و آن‌ور، هیچ‌وقت دو بار"},lang:"csharp",file:"src/ClinicReport.Api/Auth/Totp.cs",from:"public static long? Verify(string secret, string? code, DateTimeOffset now, long lastUsedStep)",lines:15},protect:{title:{en:"Unprotecting the secret at sign-in",fa:"باز کردن secret موقع ورود"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/AuthEndpoints.cs",from:"var secret = protection.CreateProtector(TwoFactorPurpose).Unprotect(user.TwoFactorSecret!);",lines:4},login:{title:{en:"Password first, then the code",fa:"اول رمز، بعد کد"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/AuthEndpoints.cs",from:"if (user.TwoFactorEnabled)",lines:10},enable:{title:{en:"On only with a matching code",fa:"روشن فقط با یک کد جور"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/AuthEndpoints.cs",from:'account.MapPost("/two-factor/enable"',lines:13}},quiz:[{q:{en:"Someone sees your code over your shoulder and types it 20 seconds after you signed in. What happens?",fa:"کسی کد شما را از پشت سرتان می‌بیند و ۲۰ ثانیه بعد از ورود شما تایپش می‌کند. چه می‌شود؟"},options:{en:["It works, the code is still in its 30-second window","It is refused: steps at or before the last one used are not accepted","It works once more, then expires"],fa:["کار می‌کند، کد هنوز در پنجره‌ی ۳۰ ثانیه‌ای است","رد می‌شود: stepهای مساوی یا قبل از آخرین step استفاده‌شده قبول نمی‌شوند","یک بار دیگر کار می‌کند و بعد منقضی می‌شود"]},answer:1,why:{en:"The matched step is saved in `TwoFactorLastStep`, so a code works once.",fa:"step جورشده در `TwoFactorLastStep` ذخیره می‌شود، پس هر کد یک بار کار می‌کند."}},{q:{en:"Why is two-factor not turned on as soon as the secret is created?",fa:"چرا ورود دومرحله‌ای به محض ساخته شدن secret روشن نمی‌شود؟"},options:{en:["A correct code first proves the phone holds the secret, so a failed scan cannot lock the user out","The secret has to be encrypted first","The QR code takes time to generate"],fa:["یک کد درست اول ثابت می‌کند گوشی secret را دارد، تا اسکن خراب کاربر را پشت در نگذارد","secret باید اول رمز شود","ساختن QR code وقت می‌برد"]},answer:0,why:{en:"`enable` verifies a code against the stored secret before setting `TwoFactorEnabled`.",fa:"`enable` قبل از گذاشتن `TwoFactorEnabled` یک کد را با secret ذخیره‌شده می‌سنجد."}},{q:{en:"A user types five wrong two-factor codes after the right password. What happens?",fa:"کاربری بعد از رمز درست پنج کد دومرحله‌ای اشتباه وارد می‌کند. چه می‌شود؟"},options:{en:["Nothing, codes are not counted","Two-factor is turned off","The account is locked for 15 minutes, as with wrong passwords"],fa:["هیچ، کدها شمرده نمی‌شوند","ورود دومرحله‌ای خاموش می‌شود","حساب، مثل رمزهای اشتباه، ۱۵ دقیقه قفل می‌شود"]},answer:2,why:{en:"A wrong code goes through the same `Failed` path, which counts towards the lockout.",fa:"کد اشتباه از همان مسیر `Failed` می‌گذرد که در قفل شدن حساب حساب می‌شود."}}]},{id:"permissions",group:"security",title:{en:"Permissions, roles and services",fa:"مجوزها، نقش‌ها و سرویس‌ها"},files:["src/ClinicReport.Api/Auth/Permissions.cs","src/ClinicReport.Api/Auth/AuthSetup.cs","src/ClinicReport.Api/Endpoints/UserEndpoints.cs"],en:[{id:"eight",h:"Eight permissions, roles built from them",p:["Endpoints check permissions, never role names, so a clinic can shape its own roles (“Echo typist”, “Reading physician”) without code. Administrator, Physician and Typist come built in; Administrator always has every permission, including one a later version adds. A role can require two-factor sign-in."],examples:["catalog","access"]},{id:"policies",h:"One policy per permission",p:["There is one authorization policy named after each permission, so an endpoint says `.RequireAuthorization(Permissions.ReportsSign)`. The fallback policy requires a signed-in user: an endpoint that names nothing still needs a sign-in, and the public ones (sign-in, settings, health) say `AllowAnonymous`."],examples:["policies"]},{id:"services",h:"Limited to some services",p:["A user can also be limited to some services (a typist who only does echo). It is a claim like the permissions; outside their services, reports, orders and templates answer 404 as if they did not exist."],examples:["service"]},{id:"admin",h:"Endpoints, and the last administrator",p:["Managing users and roles needs `users.manage`. A change that would leave no active user able to manage users is refused, or the installation would be locked for good. In the public demo every visitor may be an administrator, so these are read-only there."],data:{kind:"endpoints",only:["Users"]},examples:["last"]},{id:"tables",h:"Tables",data:{kind:"tables",only:["Roles","UserRoles"]}}],fa:[{id:"eight",h:"هشت مجوز، و نقش‌هایی ساخته از آن‌ها",p:["endpointها مجوز را چک می‌کنند، هیچ‌وقت اسم نقش را، پس کلینیک می‌تواند نقش‌های خودش را بسازد («تایپیست اکو»، «پزشک خواننده») بدون کد. Administrator، Physician و Typist از اول هستند؛ Administrator همیشه همه‌ی مجوزها را دارد، حتی مجوزی که نسخه‌ی بعدی اضافه کند. یک نقش می‌تواند ورود دومرحله‌ای را اجباری کند."],examples:["catalog","access"]},{id:"policies",h:"یک policy برای هر مجوز",p:["برای هر مجوز یک authorization policy به همان اسم هست، پس endpoint می‌گوید `.RequireAuthorization(Permissions.ReportsSign)`. fallback policy کاربر واردشده می‌خواهد: endpointی که هیچ چیز نام نبرد هم ورود لازم دارد، و endpointهای عمومی (ورود، تنظیمات، سلامت) `AllowAnonymous` می‌گویند."],examples:["policies"]},{id:"services",h:"محدود به بعضی سرویس‌ها",p:["کاربر را می‌شود به بعضی سرویس‌ها هم محدود کرد (تایپیستی که فقط اکو کار می‌کند). این هم مثل مجوزها یک claim است؛ بیرون از سرویس‌هایش، گزارش‌ها، درخواست‌ها و قالب‌ها 404 می‌دهند، انگار وجود ندارند."],examples:["service"]},{id:"admin",h:"endpointها، و آخرین admin",p:["مدیریت کاربران و نقش‌ها `users.manage` لازم دارد. تغییری که هیچ کاربر فعالی را با اجازه‌ی مدیریت کاربران باقی نگذارد رد می‌شود، وگرنه نصب برای همیشه قفل می‌شد. در دموی عمومی هر بازدیدکننده‌ای ممکن است admin باشد، پس این‌ها آن‌جا فقط‌خواندنی‌اند."],data:{kind:"endpoints",only:["Users"]},examples:["last"]},{id:"tables",h:"جدول‌ها",data:{kind:"tables",only:["Roles","UserRoles"]}}],examples:{catalog:{title:{en:"The eight permissions",fa:"هشت مجوز"},lang:"csharp",file:"src/ClinicReport.Api/Auth/Permissions.cs",from:'public const string ReportsView = "reports.view";',lines:8},access:{title:{en:"What a user may do, from their roles",fa:"کاربر چه کاری می‌تواند بکند، از نقش‌هایش"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"public static Access For(AppUser user)",lines:14},policies:{title:{en:"The fallback, then a policy per permission",fa:"fallback، بعد یک policy برای هر مجوز"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"var auth = services.AddAuthorizationBuilder()",lines:5},service:{title:{en:"May this user work on this service?",fa:"این کاربر روی این سرویس کار می‌کند؟"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"public static string[]? ServiceScope(this ClaimsPrincipal user)",lines:8},last:{title:{en:"Someone must still manage users",fa:"کسی باید هنوز کاربران را مدیریت کند"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/UserEndpoints.cs",from:"private static async Task<string?> LastAdminProblem(",lines:12}},quiz:[{q:{en:'A clinic wants an "Echo typist" role. What has to change in the code?',fa:"کلینیکی نقش «Echo typist» می‌خواهد. چه چیزی در کد باید عوض شود؟"},options:{en:["A new policy","Nothing: roles are built from permissions, and endpoints check permissions","A new migration"],fa:["یک policy تازه","هیچ: نقش‌ها از مجوزها ساخته می‌شوند و endpointها مجوز را چک می‌کنند","یک migration تازه"]},answer:1,why:{en:"No endpoint names a role, so a clinic shapes its own roles from the eight permissions.",fa:"هیچ endpointی اسم نقش را نمی‌آورد، پس کلینیک نقش‌هایش را از هشت مجوز می‌سازد."}},{q:{en:"An endpoint is added without naming any policy. Who can call it?",fa:"endpointی بدون نام بردن هیچ policyی اضافه می‌شود. چه کسی می‌تواند صدایش بزند؟"},options:{en:["Anyone, signed in or not","Only administrators","Any signed-in user, because the fallback policy requires one"],fa:["هر کسی، وارد شده یا نه","فقط مدیرها","هر کاربر واردشده، چون fallback policy آن را لازم دارد"]},answer:2,why:{en:"Public endpoints must say `AllowAnonymous` explicitly.",fa:"endpointهای عمومی باید صریحاً `AllowAnonymous` بگویند."}},{q:{en:"An administrator tries to remove `users.manage` from the last active user who has it. What happens?",fa:"مدیری سعی می‌کند `users.manage` را از آخرین کاربر فعالی که آن را دارد بردارد. چه می‌شود؟"},options:{en:["It is refused, or the installation would be locked for good","It is allowed; the next start restores it","It is allowed with a warning"],fa:["رد می‌شود، وگرنه نصب برای همیشه قفل می‌شد","مجاز است؛ شروع بعدی آن را برمی‌گرداند","با یک هشدار مجاز است"]},answer:0,why:{en:"`LastAdminProblem` checks that someone active can still manage users.",fa:"`LastAdminProblem` چک می‌کند که هنوز کسی فعال بتواند کاربرها را مدیریت کند."}}]},{id:"audit",group:"security",title:{en:"The audit log, and CSRF",fa:"audit log، و CSRF"},files:["src/ClinicReport.Api/Auth/SecurityLog.cs","src/ClinicReport.Api/Auth/AuthSetup.cs","web/src/pages/Audit.tsx"],en:[{id:"two",h:"Two trails",p:["Every change to a report is in `Changes` (see Every change through one service). Apart from that, `SecurityEvents` records sign-ins and failures, lockouts, account and role changes, signatures, broken glass, and who opened which patient's report, the access log PHIPA and HIPAA ask for. Rows are only ever added.","`Add` only puts the event in the current DbContext, so it is saved by the caller's own `SaveChanges`, together with the change it describes; `WriteAsync` is for events that stand alone and saves at once. A long detail is cut to 500 characters, and the caller's IP address is kept."],examples:["add"]},{id:"views",h:"Opening a report, logged once",p:["Opening the same report again within 10 minutes is not logged again, so moving between tabs does not bury the log in duplicates."],examples:["viewed"]},{id:"endpoint",h:"Reading it",p:["`audit.view`, 200 rows at a time, filtered by type, user, report or dates, newest first.",'The next page is asked for with `before`, the id of the last row shown: newer rows written meanwhile do not shift the pages, as an offset would. Each row comes with the names of the user who acted and the user acted upon, and the patient as "Last, First (MRN)".'],data:{kind:"endpoints",only:["Audit"]},examples:["page"]},{id:"csrf",h:"CSRF: a header a browser cannot forge",p:["On top of SameSite=Strict, every POST, PUT, PATCH or DELETE to `/api` must carry `X-ClinicReport`. A page on another site cannot add a custom header without a CORS preflight, which this API never allows; the page's own client always sends it."],examples:["csrf","header"]},{id:"table",h:"Table",data:{kind:"tables",only:["SecurityEvents"]}}],fa:[{id:"two",h:"دو رد",p:["هر تغییر گزارش در `Changes` است (بخش هر تغییر از یک سرویس را ببینید). جدا از آن، `SecurityEvents` ورودها و شکست‌ها، قفل شدن‌ها، تغییرهای حساب و نقش، امضاها، شکستن شیشه، و این‌که چه کسی گزارش کدام بیمار را باز کرده را ثبت می‌کند؛ همان access log که PHIPA و HIPAA می‌خواهند. ردیف‌ها فقط اضافه می‌شوند.","`Add` فقط رویداد را در DbContext فعلی می‌گذارد، پس با همان `SaveChanges` خود کد صدازننده، همراه با تغییری که توصیف می‌کند، ذخیره می‌شود؛ `WriteAsync` برای رویدادهایی است که تنها هستند و فوراً ذخیره می‌کند. جزئیات طولانی تا ۵۰۰ کاراکتر بریده می‌شود و آدرس IP درخواست‌دهنده نگه داشته می‌شود."],examples:["add"]},{id:"views",h:"باز کردن گزارش، یک بار ثبت می‌شود",p:["باز کردن دوباره‌ی همان گزارش در ۱۰ دقیقه دوباره ثبت نمی‌شود، پس جابه‌جا شدن بین tabها log را زیر تکراری‌ها دفن نمی‌کند."],examples:["viewed"]},{id:"endpoint",h:"خواندنش",p:["`audit.view`، هر بار ۲۰۰ ردیف، با filter نوع، کاربر، گزارش یا تاریخ، تازه‌ترین اول.","صفحه‌ی بعد با `before`، شناسه‌ی آخرین ردیفی که نشان داده شده، خواسته می‌شود: ردیف‌های تازه‌ای که در این فاصله نوشته شده‌اند صفحه‌ها را جابه‌جا نمی‌کنند، کاری که offset می‌کرد. هر ردیف با اسم کاربری که کار را کرده و کاربری که کار رویش انجام شده، و بیمار به شکل «نام خانوادگی، نام (MRN)» می‌آید."],data:{kind:"endpoints",only:["Audit"]},examples:["page"]},{id:"csrf",h:"CSRF: هدری که مرورگر نمی‌تواند جعل کند",p:["علاوه بر SameSite=Strict، هر POST، PUT، PATCH یا DELETE به `/api` باید `X-ClinicReport` داشته باشد. صفحه‌ای در سایت دیگر بدون CORS preflight نمی‌تواند هدر سفارشی اضافه کند، و این API هیچ‌وقت آن را اجازه نمی‌دهد؛ client خود صفحه همیشه آن را می‌فرستد."],examples:["csrf","header"]},{id:"table",h:"جدول",data:{kind:"tables",only:["SecurityEvents"]}}],examples:{add:{title:{en:"One security event",fa:"یک رویداد امنیتی"},lang:"csharp",file:"src/ClinicReport.Api/Auth/SecurityLog.cs",from:"public void Add(string type, int? actor",lines:12},viewed:{title:{en:"A view, once per 10 minutes",fa:"یک بار دیدن، هر ۱۰ دقیقه یک بار"},lang:"csharp",file:"src/ClinicReport.Api/Auth/SecurityLog.cs",from:"public async Task ReportViewedAsync(int userId, int reportId, int patientId, CancellationToken ct)",lines:9},csrf:{title:{en:"The header check",fa:"چک هدر"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"public static IApplicationBuilder UseCsrfHeaderCheck(this IApplicationBuilder app) => app.Use(async (ctx, next) =>",lines:11},header:{title:{en:"What the page sends",fa:"چیزی که صفحه می‌فرستد"},lang:"typescript",file:"web/src/api.ts",from:"headers: {",lines:5},page:{title:{en:"Filters, then 200 rows before an id",fa:"فیلترها، بعد ۲۰۰ ردیف قبل از یک شناسه"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/UserEndpoints.cs",from:"if (before is not null)",lines:3}},quiz:[{q:{en:"A physician moves between the tabs of the same report for five minutes. How many `ReportViewed` rows are written?",fa:"پزشکی پنج دقیقه بین tabهای یک گزارش جابه‌جا می‌شود. چند ردیف `ReportViewed` نوشته می‌شود؟"},options:{en:["One per tab switch","One: opening again within 10 minutes is not logged again","None, views are not logged"],fa:["برای هر جابه‌جایی یکی","یکی: باز کردن دوباره در عرض ۱۰ دقیقه دوباره ثبت نمی‌شود","هیچ، دیدن ثبت نمی‌شود"]},answer:1,why:{en:"`ReportViewedAsync` looks for the same user and report within `ViewDedupWindow` first.",fa:"`ReportViewedAsync` اول دنبال همان کاربر و گزارش در `ViewDedupWindow` می‌گردد."}},{q:{en:"Why is the next page of the log asked for by `before` an id rather than by an offset?",fa:"چرا صفحه‌ی بعد لاگ با `before` یک شناسه خواسته می‌شود و نه با offset؟"},options:{en:["New rows written meanwhile would shift an offset and repeat rows","SQLite has no OFFSET","Ids are encrypted"],fa:["ردیف‌های تازه‌ای که در این فاصله نوشته شوند offset را جابه‌جا می‌کردند و ردیف‌ها تکرار می‌شدند","SQLite دستور OFFSET ندارد","شناسه‌ها رمز شده‌اند"]},answer:0,why:{en:"The log grows all the time; `Id < before` always continues exactly where the last page ended.",fa:"لاگ مدام بزرگ می‌شود؛ `Id < before` همیشه دقیقاً از جایی که صفحه‌ی قبل تمام شد ادامه می‌دهد."}},{q:{en:"A page on another site posts a form to `/api/reports/1/sign`. Why does it fail even if a cookie were sent?",fa:"صفحه‌ای در سایت دیگر فرمی به `/api/reports/1/sign` post می‌کند. چرا حتی اگر کوکی فرستاده شود شکست می‌خورد؟"},options:{en:["Signing needs a GET","The form has no JSON body","It cannot add the `X-ClinicReport` header without a CORS preflight, which the API never allows"],fa:["امضا GET لازم دارد","فرم بدنه‌ی JSON ندارد","بدون CORS preflight نمی‌تواند هدر `X-ClinicReport` را اضافه کند، که API هیچ‌وقت اجازه نمی‌دهد"]},answer:2,why:{en:"The header check sits on top of SameSite=Strict for every unsafe `/api` call.",fa:"چک هدر، علاوه بر SameSite=Strict، روی هر فراخوانی ناامن `/api` هست."}}]},{id:"clinichub-signin",group:"clinichub",title:{en:"Signing in through ClinicHub",fa:"ورود از طریق ClinicHub"},files:["src/ClinicReport.Api/Auth/ClinicHubConnection.cs","src/ClinicReport.Api/Endpoints/AuthEndpoints.cs"],en:[{id:"switch",h:"One setting switches it on",p:["With `ClinicHub:Authority` set, ClinicReport becomes one of ClinicHub's applications: people sign in there (OpenID Connect, authorization code with PKCE) and choose the clinic there. Without it nothing of this is registered and the app runs with its own accounts. Connected, the local account endpoints answer 409."],examples:["managed"]},{id:"oidc",h:"The OpenID Connect client",p:["The code comes back in the query string rather than a cross-site form post, so the correlation cookies can stay SameSite=Lax over plain HTTP in development, and the sign-in cookie itself is Lax when connected, since the browser arrives from ClinicHub. Of the tokens, only the refresh token (for the re-checks) and the id token (for the sign-out) are kept: every app's cookies travel together on localhost."],examples:["oidc","lax"]},{id:"local",h:"ClinicHub's person, a local user",p:["At sign-in the person becomes a user of that clinic's database, linked by ClinicHub's account id, so signatures, addenda and the access log point at someone. A local account with the same user name from before the clinic connected is taken over with its history. Permissions come from ClinicHub (its `clinicreport:reports.sign` arrives as `reports.sign`), and only those ClinicReport knows are kept; the services a person may work on stay ClinicReport's."],examples:["user","permissions"]},{id:"recheck",h:"ClinicHub has the last word",p:["Every request checks the local user is still active. Every few minutes the session is also checked with ClinicHub using the refresh token: a refusal (roles removed, signed out everywhere, account closed) ends it here; ClinicHub being unreachable is tolerated for 30 minutes."],examples:["recheck"]},{id:"databases",h:"One SQLite file per clinic",p:["The clinic's short name in the session picks the database of each request (`clinicreport-{clinic}.db`), created with the roles and bundled templates the first time. The name is checked (lower-case letters, digits and dashes) before it goes into a file name. One ClinicReport serves several clinics without their reports ever sharing a table."],examples:["create","scoped"]}],fa:[{id:"switch",h:"یک تنظیم روشنش می‌کند",p:["با تنظیم `ClinicHub:Authority`، ClinicReport یکی از اپ‌های ClinicHub می‌شود: آدم‌ها آن‌جا وارد می‌شوند (OpenID Connect، authorization code با PKCE) و کلینیک را آن‌جا انتخاب می‌کنند. بدون آن هیچ‌کدام از این‌ها ثبت نمی‌شود و اپ با حساب‌های خودش کار می‌کند. در حالت متصل، endpointهای حساب محلی 409 می‌دهند."],examples:["managed"]},{id:"oidc",h:"client OpenID Connect",p:["code در query string برمی‌گردد نه با form post بین‌سایتی، پس correlation cookieها در development روی HTTP ساده می‌توانند SameSite=Lax بمانند، و خود کوکی ورود در حالت متصل Lax است، چون مرورگر از ClinicHub می‌رسد. از tokenها فقط refresh token (برای چک‌های دوباره) و id token (برای خروج) نگه داشته می‌شوند: روی localhost کوکی‌های همه‌ی اپ‌ها با هم سفر می‌کنند."],examples:["oidc","lax"]},{id:"local",h:"آدمِ ClinicHub، یک کاربر محلی",p:["موقع ورود، آن آدم کاربر دیتابیس همان کلینیک می‌شود، با id حسابش در ClinicHub، تا امضاها، addendumها و access log به کسی اشاره کنند. حساب محلی‌ای با همان نام کاربری از قبل از وصل شدن کلینیک با تاریخچه‌اش تحویل گرفته می‌شود. مجوزها از ClinicHub می‌آیند (`clinicreport:reports.sign` آن‌جا این‌جا `reports.sign` می‌شود)، و فقط آن‌هایی که ClinicReport می‌شناسد نگه داشته می‌شوند؛ سرویس‌هایی که آدم روی آن‌ها کار می‌کند مال ClinicReport می‌مانند."],examples:["user","permissions"]},{id:"recheck",h:"حرف آخر را ClinicHub می‌زند",p:["هر درخواست چک می‌کند که کاربر محلی هنوز فعال است. هر چند دقیقه هم session با refresh token از ClinicHub پرسیده می‌شود: رد شدن (نقش‌ها گرفته شده، خروج از همه جا، حساب بسته) آن را این‌جا تمام می‌کند؛ در دسترس نبودن ClinicHub تا ۳۰ دقیقه تحمل می‌شود."],examples:["recheck"]},{id:"databases",h:"یک فایل SQLite برای هر کلینیک",p:["اسم کوتاه کلینیک در session دیتابیس هر درخواست را انتخاب می‌کند (`clinicreport-{clinic}.db`)، که بار اول با نقش‌ها و قالب‌های همراه ساخته می‌شود. اسم قبل از رفتن در اسم فایل چک می‌شود (حروف کوچک، رقم و خط تیره). یک ClinicReport به چند کلینیک خدمت می‌کند بدون این‌که گزارش‌هایشان هیچ‌وقت در یک جدول باشند."],examples:["create","scoped"]}],examples:{managed:{title:{en:"Connected: the local endpoints only say so",fa:"متصل: endpointهای محلی فقط همین را می‌گویند"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/AuthEndpoints.cs",from:"// Connected to ClinicHub: these exist only to say so",lines:5},oidc:{title:{en:"Code flow with PKCE, answer in the query",fa:"code flow با PKCE، جواب در query"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:'auth.AddOpenIdConnect(Scheme, "ClinicHub", o =>',lines:16},lax:{title:{en:"Lax when connected",fa:"Lax در حالت متصل"},lang:"csharp",file:"src/ClinicReport.Api/Auth/AuthSetup.cs",from:"// Connected: the browser arrives from ClinicHub's sign-in",lines:2},user:{title:{en:"Found, taken over, or created",fa:"پیدا شد، تحویل گرفته شد، یا ساخته شد"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:'var externalId = $"clinichub:{hub.FindFirstValue("sub")}";',lines:15},permissions:{title:{en:"Only the permissions ClinicReport knows",fa:"فقط مجوزهایی که ClinicReport می‌شناسد"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:"// Only keys ClinicReport knows",lines:2},recheck:{title:{en:"Asking ClinicHub again",fa:"دوباره پرسیدن از ClinicHub"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:"if (DateTime.UtcNow - checkedAt >= TimeSpan.FromMinutes(options.RecheckMinutes))",lines:20},create:{title:{en:"A checked name, then a file",fa:"اسم چک‌شده، بعد فایل"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:"public ClinicReportDbContext Create(string slug)",lines:7},scoped:{title:{en:"The request's database",fa:"دیتابیس درخواست"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:"// The database of the request is the signed-in person's clinic.",lines:8}},quiz:[{q:{en:"`ClinicHub:Authority` is empty. What of the ClinicHub sign-in is registered?",fa:"`ClinicHub:Authority` خالی است. چه بخشی از ورود ClinicHub ثبت می‌شود؟"},options:{en:["Nothing: the app runs with its own accounts","The OpenID Connect client, unused","Only the re-checks"],fa:["هیچ: اپ با حساب‌های خودش اجرا می‌شود","client‌ی OpenID Connect، بدون استفاده","فقط چک‌های دوباره"]},answer:0,why:{en:"One setting switches the whole connected mode on.",fa:"یک تنظیم کل حالت متصل را روشن می‌کند."}},{q:{en:"Someone had a local account `jlee` before the clinic connected and signs in through ClinicHub as `jlee`. What happens?",fa:"کسی قبل از اتصال کلینیک حساب محلی `jlee` داشته و حالا با ClinicHub به‌عنوان `jlee` وارد می‌شود. چه می‌شود؟"},options:{en:["A second user is created","The local account is taken over, with its history","Sign-in is refused"],fa:["کاربر دومی ساخته می‌شود","حساب محلی، با سابقه‌اش، تصاحب می‌شود","ورود رد می‌شود"]},answer:1,why:{en:"Signatures and addenda made before stay linked to the same person.",fa:"امضاها و addendumهای قبلی به همان شخص وصل می‌مانند."}},{q:{en:"Why is the clinic's short name checked before it becomes part of a database file name?",fa:"چرا اسم کوتاه کلینیک قبل از این‌که بخشی از اسم فایل دیتابیس شود چک می‌شود؟"},options:{en:["SQLite file names must be short","To keep names sorted","So nothing like a path or dots can reach the file name"],fa:["اسم فایل‌های SQLite باید کوتاه باشد","برای مرتب ماندن اسم‌ها","تا چیزی مثل مسیر یا نقطه به اسم فایل نرسد"]},answer:2,why:{en:"Only lower-case letters, digits and dashes are allowed in `clinicreport-{clinic}.db`.",fa:"در `clinicreport-{clinic}.db` فقط حروف کوچک، رقم و خط تیره مجاز است."}}]},{id:"orders",group:"clinichub",title:{en:"Orders arriving over FHIR",fa:"درخواست‌هایی که با FHIR می‌رسند"},files:["src/ClinicReport.Api/Endpoints/OrderEndpoints.cs","src/ClinicReport.Api/Auth/ClinicHubConnection.cs","web/src/pages/Worklist.tsx"],en:[{id:"endpoints",h:"Endpoints",p:["These exist only when connected. `/fhir` is for ClinicHub itself: a bearer token ClinicHub signed for ClinicReport, with the scope `orders` and a valid clinic name. `/api/orders` is the worklist's *Ordered from ClinicHub*."],data:{kind:"endpoints",only:["Order","Orders"]},examples:["policy"]},{id:"bundle",h:"One endpoint, three messages",p:["ClinicHub posts a FHIR R4 transaction Bundle. A lone Patient with a link is a merge of two records; revoked ServiceRequests withdraw exams; anything else is new orders: a Patient, the requesting Practitioner and one ServiceRequest per exam. A malformed Bundle is answered with an OperationOutcome saying what is wrong."],examples:["dispatch"]},{id:"codes",h:"The exam is a template key",p:["Each ServiceRequest is coded in `urn:clinicreport:template` with the key of an active template (`echo-tte`, `ecg-12-lead`). One unknown key refuses the whole Bundle, before anything is saved."],examples:["codes"]},{id:"once",h:"Sent twice, saved once",p:["An order is known by the clinic and ClinicHub's id (`slug:id`, unique in the table), so a retry after a timeout finds the order it already saved and answers the same. ClinicHub's register is the source of truth for the patient's details, which are updated with every order."],examples:["existing"]},{id:"start",h:"Starting the exam",p:["*Start report* makes a draft on the template's latest published version, with the order's indication and referring physician in the header, and marks the order started. A withdrawal that arrives after that is refused with 409: the clinic has to speak to the reading physician."],examples:["cancel"]},{id:"table",h:"Table",data:{kind:"tables",only:["ReportOrders"]}}],fa:[{id:"endpoints",h:"endpointها",p:["این‌ها فقط در حالت متصل وجود دارند. `/fhir` برای خود ClinicHub است: bearer tokenی که ClinicHub برای ClinicReport امضا کرده، با scope `orders` و اسم کلینیک معتبر. `/api/orders` همان *Ordered from ClinicHub* در worklist است."],data:{kind:"endpoints",only:["Order","Orders"]},examples:["policy"]},{id:"bundle",h:"یک endpoint، سه پیام",p:["ClinicHub یک transaction Bundle از FHIR R4 می‌فرستد. یک Patient تنها با link ادغام دو پرونده است؛ ServiceRequestهای revoked معاینه را پس می‌گیرند؛ هر چیز دیگر درخواست تازه است: یک Patient، پزشک درخواست‌دهنده (Practitioner) و یک ServiceRequest برای هر معاینه. Bundle بدشکل با یک OperationOutcome جواب می‌گیرد که می‌گوید چه چیزش ایراد دارد."],examples:["dispatch"]},{id:"codes",h:"معاینه، key یک قالب است",p:["هر ServiceRequest در `urn:clinicreport:template` با key یک قالب فعال کد می‌خورد (`echo-tte`، `ecg-12-lead`). یک key ناشناخته کل Bundle را رد می‌کند، قبل از این‌که چیزی ذخیره شود."],examples:["codes"]},{id:"once",h:"دو بار فرستاده، یک بار ذخیره",p:["هر درخواست با کلینیک و id ClinicHub شناخته می‌شود (`slug:id`، یکتا در جدول)، پس تلاش دوباره بعد از timeout درخواستی را که قبلاً ذخیره کرده پیدا می‌کند و همان جواب را می‌دهد. فهرست ClinicHub منبع درست مشخصات بیمار است، که با هر درخواست به‌روز می‌شود."],examples:["existing"]},{id:"start",h:"شروع معاینه",p:["*Start report* یک پیش‌نویس روی آخرین نسخه‌ی منتشرشده‌ی قالب می‌سازد، با indication و پزشک ارجاع‌دهنده‌ی درخواست در سربرگ، و درخواست را شروع‌شده علامت می‌زند. پس گرفتنی که بعد از آن برسد با 409 رد می‌شود: کلینیک باید با پزشک خواننده صحبت کند."],examples:["cancel"]},{id:"table",h:"جدول",data:{kind:"tables",only:["ReportOrders"]}}],examples:{policy:{title:{en:"ClinicHub's token, for orders",fa:"token ClinicHub، برای درخواست‌ها"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ClinicHubConnection.cs",from:"services.AddAuthorizationBuilder().AddPolicy(OrdersPolicy",lines:3},dispatch:{title:{en:"Which kind of Bundle",fa:"کدام نوع Bundle"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:'var entries = bundle["entry"]',lines:8},codes:{title:{en:"Every exam must be a template here",fa:"هر معاینه باید این‌جا قالب داشته باشد"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"var keys = orders.Select(o =>",lines:5},existing:{title:{en:"The same order again",fa:"همان درخواست دوباره"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"var existing = await db.ReportOrders.SingleOrDefaultAsync(x => x.ExternalId == externalId);",lines:6},cancel:{title:{en:"Too late to withdraw",fa:"برای پس گرفتن دیر شده"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"if (order.Status == ReportOrderStatus.Started)",lines:3}},quiz:[{q:{en:"A Bundle orders two exams; one template key is unknown. What is saved?",fa:"یک Bundle دو معاینه درخواست می‌کند؛ کلید یکی از قالب‌ها ناشناخته است. چه چیزی ذخیره می‌شود؟"},options:{en:["Nothing: the whole Bundle is refused before anything is saved","The known exam only","Both, the unknown one as a draft"],fa:["هیچ: کل Bundle قبل از ذخیره‌ی هر چیزی رد می‌شود","فقط معاینه‌ی شناخته‌شده","هر دو، ناشناخته به شکل پیش‌نویس"]},answer:0,why:{en:"Keys are checked first; an OperationOutcome names the unknown one.",fa:"کلیدها اول چک می‌شوند؛ یک OperationOutcome ناشناخته را نام می‌برد."}},{q:{en:"ClinicHub retries an order after a timeout. Why is it not saved twice?",fa:"ClinicHub بعد از timeout یک درخواست را دوباره می‌فرستد. چرا دو بار ذخیره نمی‌شود؟"},options:{en:["ClinicHub never retries","The order is known by `slug:id`, unique in the table, so the retry finds it","SQLite rejects identical rows"],fa:["ClinicHub هیچ‌وقت دوباره نمی‌فرستد","درخواست با `slug:id` شناخته می‌شود که در جدول یکتاست، پس تلاش دوباره پیدایش می‌کند","SQLite ردیف‌های یکسان را رد می‌کند"]},answer:1,why:{en:"The answer to the retry is the same as to the first send.",fa:"جواب تلاش دوباره همان جواب ارسال اول است."}},{q:{en:"The clinic withdraws an exam after *Start report* was pressed. What is the answer?",fa:"کلینیک بعد از زدن *Start report* معاینه‌ای را پس می‌گیرد. جواب چیست؟"},options:{en:["The draft report is deleted","The order is cancelled and the draft kept","409: the clinic has to speak to the reading physician"],fa:["گزارش پیش‌نویس حذف می‌شود","درخواست لغو می‌شود و پیش‌نویس می‌ماند","409: کلینیک باید با پزشک گزارش‌کننده صحبت کند"]},answer:2,why:{en:"Once an exam has started, a withdrawal is a conversation, not an automatic change.",fa:"وقتی معاینه شروع شده، پس گرفتن یک گفتگوست، نه یک تغییر خودکار."}}]},{id:"restricted",group:"clinichub",title:{en:"Restricted items: breaking the glass",fa:"موارد محدودشده: شکستن شیشه"},files:["src/ClinicReport.Api/Auth/ConfidentialityGate.cs","src/ClinicReport.Api/Endpoints/OrderEndpoints.cs","src/ClinicReport.Api/Endpoints/ReportEndpoints.cs","web/src/components/RestrictedGate.tsx"],en:[{id:"label",h:"The label comes with the order",p:["When the patient has a consent directive at the clinic, ClinicHub labels the order (`R` restricted, `V` very restricted, HL7's confidentiality codes). `U`, `L`, `M` and `N` mean no restriction; any other code of that system is treated as `R`."],examples:["label"]},{id:"gate",h:"Closed until someone says why",p:["A labelled order or report answers 403 `restricted` to everyone. `POST …/override` with a reason of at least 10 characters opens it for that user and that item for one hour, and writes who, what and why to the security log (`RestrictedOverride`). The openings live in memory: a restart closes them, which is the safe way to fail. Whoever opens the order carries on with its report."],examples:["gate","carry"]},{id:"lists",h:"Listed, but not who it is for",p:["The worklists still show a closed item, so it is not lost, with the patient as “Restricted” and no MRN or indication. On the report routes the check is a filter on the whole `/{id}` group."],examples:["hide","filter"]},{id:"ui",h:"Asking on the page",p:["The editor and the worklist catch the 403 and show a box asking why, instead of a browser prompt; the button stays disabled until the reason is 10 characters long."],examples:["ui"]}],fa:[{id:"label",h:"برچسب با درخواست می‌آید",p:["وقتی بیمار در کلینیک consent directive دارد، ClinicHub به درخواست برچسب می‌زند (`R` محدود، `V` خیلی محدود، کدهای محرمانگی HL7). `U`، `L`، `M` و `N` یعنی محدودیتی نیست؛ هر کد دیگر از آن سیستم `R` حساب می‌شود."],examples:["label"]},{id:"gate",h:"بسته، تا کسی بگوید چرا",p:["درخواست یا گزارش برچسب‌دار به همه 403 `restricted` می‌دهد. `POST …/override` با دلیلی دست‌کم ۱۰ کاراکتری آن را برای همان کاربر و همان مورد یک ساعت باز می‌کند، و چه کسی، چه چیزی و چرا را در security log می‌نویسد (`RestrictedOverride`). باز شدن‌ها در حافظه‌اند: restart آن‌ها را می‌بندد، که شکست امن همین است. کسی که درخواست را باز کرده با گزارشش ادامه می‌دهد."],examples:["gate","carry"]},{id:"lists",h:"در فهرست هست، ولی نه این‌که مال کیست",p:["worklistها مورد بسته را باز هم نشان می‌دهند، تا گم نشود، با بیمار به‌صورت «Restricted» و بدون MRN یا indication. در routeهای گزارش، این چک filterی روی کل گروه `/{id}` است."],examples:["hide","filter"]},{id:"ui",h:"پرسیدن در خود صفحه",p:["ویرایشگر و worklist آن 403 را می‌گیرند و به‌جای prompt مرورگر کادری نشان می‌دهند که می‌پرسد چرا؛ دکمه تا وقتی دلیل ۱۰ کاراکتر نشده غیرفعال می‌ماند."],examples:["ui"]}],examples:{label:{title:{en:"Reading the label",fa:"خواندن برچسب"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"public static string? Confidentiality(JsonNode? resource)",lines:8},gate:{title:{en:"One user, one item, one hour",fa:"یک کاربر، یک مورد، یک ساعت"},lang:"csharp",file:"src/ClinicReport.Api/Auth/ConfidentialityGate.cs",from:"public class ConfidentialityGate(IMemoryCache cache, TimeProvider clock)",to:"public static bool ReasonOk"},carry:{title:{en:"From the order to its report",fa:"از درخواست به گزارشش"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"if (order.Confidentiality is not null)",lines:2},hide:{title:{en:"Listed as Restricted",fa:"در فهرست به‌صورت Restricted"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/OrderEndpoints.cs",from:"// A restricted order is listed, so it is not lost",lines:2},filter:{title:{en:"The filter on the report routes",fa:"filter روی routeهای گزارش"},lang:"csharp",file:"src/ClinicReport.Api/Endpoints/ReportEndpoints.cs",from:"private static async ValueTask<object?> ConfidentialityFilter(",lines:10},ui:{title:{en:"The reason box",fa:"کادر دلیل"},lang:"typescript",file:"web/src/components/RestrictedGate.tsx",from:"export function RestrictedGate(",to:"</section>"}},quiz:[{q:{en:"An order arrives labelled with a confidentiality code other than U, L, M, N or V. How is it treated?",fa:"درخواستی با کد confidentiality غیر از U، L، M، N یا V می‌رسد. چطور با آن رفتار می‌شود؟"},options:{en:["As unrestricted","As `R`, restricted","It is refused"],fa:["بدون محدودیت","به‌عنوان `R`، محدود","رد می‌شود"]},answer:1,why:{en:"Any other code of that system is treated as `R`, so an unexpected code fails closed.",fa:"هر کد دیگری از آن سیستم `R` حساب می‌شود، پس کد غیرمنتظره به سمت بسته شکست می‌خورد."}},{q:{en:"Why are closed items still listed on the worklist?",fa:"چرا موردهای بسته هنوز در worklist فهرست می‌شوند؟"},options:{en:['So they are not lost; the patient shows as "Restricted" with no MRN or indication',"Because the filter cannot hide rows","So anyone can open them without a reason"],fa:["تا گم نشوند؛ بیمار به شکل «Restricted» و بدون MRN یا indication نشان داده می‌شود","چون filter نمی‌تواند ردیف را پنهان کند","تا هر کسی بدون دلیل بازشان کند"]},answer:0,why:{en:"The work must still be done; only who it is for is hidden until someone says why.",fa:"کار باید انجام شود؛ فقط این‌که برای چه کسی است تا وقتی کسی دلیل بیاورد پنهان می‌ماند."}},{q:{en:"You open a restricted order with a reason and start its report. What about the report?",fa:"یک درخواست محدود را با دلیل باز می‌کنید و گزارشش را شروع می‌کنید. گزارش چه می‌شود؟"},options:{en:["It needs a second reason","It is unrestricted for everyone","You carry on with it: the opening carries over to its report"],fa:["دلیل دوم لازم دارد","برای همه بدون محدودیت می‌شود","با آن ادامه می‌دهید: باز شدن به گزارشش منتقل می‌شود"]},answer:2,why:{en:"Whoever opens the order carries on with its report, still for that user only.",fa:"کسی که درخواست را باز می‌کند با گزارشش ادامه می‌دهد، باز هم فقط برای همان کاربر."}}]},{id:"results-out",group:"clinichub",title:{en:"Results back, and the accounting",fa:"جواب‌ها برمی‌گردند، و حسابداری"},files:["src/ClinicReport.Api/Reports/ResultSender.cs","src/ClinicReport.Api/Reports/FinanceSender.cs","src/ClinicReport.Api/Reports/ReportService.cs"],en:[{id:"queued",h:"Queued with the signature",p:["Signing a report from an order adds a result message to the clinic database's outbox, saved in the same `SaveChanges` as the signature: either both happen or neither. An addendum queues the result again as `amended`, with every addendum appended to the conclusion."],examples:["enqueue"]},{id:"shape",h:"A DiagnosticReport that names the order",p:["The result is a FHIR DiagnosticReport whose `basedOn` names ClinicHub's order, which is how ClinicHub finds the clinic and the exam. It carries the conclusion, who signed, the order's confidentiality label back, and a link to the full printable report here."],examples:["basedon","link"]},{id:"send",h:"Delivery and retries",p:["A background worker goes through every clinic database it finds on disk, sends what is due with a client-credentials token (scope `results`, cached until a minute before it expires) and, after a failure, waits 10 s, 20 s, 40 s… up to 30 minutes, 12 attempts at most. A `401` drops the cached token. `ClinicHub:ResultsUrl` can send them through IntegrationHub instead of straight to ClinicHub."],examples:["clinics","retry"]},{id:"money",h:"To the accounting, without health information",p:["With `ClinicHub:FinanceUrl` set, each signed report of an ordered exam becomes an invoice to OHIP for FinancePowerApp: the template's technical fee and professional fee, by department (Echo or ECG). No patient and no findings leave. Each document has an id that never changes (`report:{id}:signed`) and is recorded in `FinanceExports` once accepted, so it is sent once."],examples:["finance"]},{id:"tables",h:"Tables",data:{kind:"tables",only:["ResultMessages","FinanceExports"]}}],fa:[{id:"queued",h:"همراه امضا، در صف",p:["امضای گزارشی که از یک درخواست آمده یک پیام جواب به outbox دیتابیس کلینیک اضافه می‌کند، ذخیره‌شده در همان `SaveChanges` امضا: یا هر دو اتفاق می‌افتند یا هیچ‌کدام. addendum جواب را دوباره به‌صورت `amended` در صف می‌گذارد، با همه‌ی addendumها چسبیده به نتیجه‌گیری."],examples:["enqueue"]},{id:"shape",h:"DiagnosticReportی که درخواست را نام می‌برد",p:["جواب یک DiagnosticReport از FHIR است که `basedOn`اش درخواست ClinicHub را نام می‌برد، و ClinicHub با همین کلینیک و معاینه را پیدا می‌کند. نتیجه‌گیری، امضاکننده، برچسب محرمانگی درخواست (برگشتی) و لینکی به گزارش کامل قابل چاپ در این‌جا را همراه دارد."],examples:["basedon","link"]},{id:"send",h:"رساندن و تلاش دوباره",p:["یک worker پس‌زمینه همه‌ی دیتابیس‌های کلینیک را که روی دیسک پیدا می‌کند می‌گردد، چیزی را که وقتش رسیده با یک token از نوع client credentials می‌فرستد (scope `results`، cache‌شده تا یک دقیقه قبل از انقضا) و بعد از هر شکست ۱۰ ثانیه، ۲۰ ثانیه، ۴۰ ثانیه… تا ۳۰ دقیقه صبر می‌کند، حداکثر ۱۲ بار. `401` token cache‌شده را دور می‌اندازد. `ClinicHub:ResultsUrl` می‌تواند آن‌ها را به‌جای مستقیم به ClinicHub، از IntegrationHub بفرستد."],examples:["clinics","retry"]},{id:"money",h:"به حسابداری، بدون اطلاعات سلامت",p:["با تنظیم `ClinicHub:FinanceUrl`، هر گزارش امضاشده‌ی یک معاینه‌ی درخواستی یک فاکتور به OHIP برای FinancePowerApp می‌شود: دستمزد فنی و حرفه‌ای قالب، به تفکیک بخش (Echo یا ECG). هیچ بیمار و هیچ یافته‌ای بیرون نمی‌رود. هر سند شناسه‌ای دارد که هیچ‌وقت عوض نمی‌شود (`report:{id}:signed`) و بعد از قبول شدن در `FinanceExports` ثبت می‌شود، پس یک بار فرستاده می‌شود."],examples:["finance"]},{id:"tables",h:"جدول‌ها",data:{kind:"tables",only:["ResultMessages","FinanceExports"]}}],examples:{enqueue:{title:{en:"In the signature's save",fa:"در ذخیره‌ی امضا"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ReportService.cs",from:"if (order is not null)",lines:5},basedon:{title:{en:"Naming ClinicHub's order",fa:"نام بردن درخواست ClinicHub"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ResultSender.cs",from:'["basedOn"] = new JsonArray(new JsonObject',lines:4},link:{title:{en:"A link to the full report",fa:"لینکی به گزارش کامل"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ResultSender.cs",from:'["presentedForm"] = publicUrl',lines:3},clinics:{title:{en:"The clinics: the files the pattern matches",fa:"کلینیک‌ها: فایل‌هایی که الگو با آن‌ها جور است"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ResultSender.cs",from:"public IEnumerable<string> Clinics()",lines:13},retry:{title:{en:"Doubling pauses",fa:"مکث‌های دوبرابرشونده"},lang:"csharp",file:"src/ClinicReport.Api/Reports/ResultSender.cs",from:"m.NextAttemptAt = now.AddSeconds(Math.Min(10 * Math.Pow(2",lines:3},finance:{title:{en:"A signed report as an invoice",fa:"گزارش امضاشده به‌صورت فاکتور"},lang:"csharp",file:"src/ClinicReport.Api/Reports/FinanceSender.cs",from:"foreach (var r in signed)",lines:16}},quiz:[{q:{en:"Why is the result message saved in the same `SaveChanges` as the signature?",fa:"چرا پیام جواب در همان `SaveChanges` امضا ذخیره می‌شود؟"},options:{en:["Either both happen or neither, so no signed report is left unsent","SQLite allows one save per request","To send it faster"],fa:["یا هر دو انجام می‌شوند یا هیچ‌کدام، پس هیچ گزارش امضاشده‌ای بی‌ارسال نمی‌ماند","SQLite در هر درخواست یک ذخیره اجازه می‌دهد","برای سریع‌تر فرستادن"]},answer:0,why:{en:"An outbox written with the business change is delivered later by the worker.",fa:"outboxی که همراه تغییر اصلی نوشته می‌شود بعداً توسط worker تحویل می‌شود."}},{q:{en:"An addendum is added to a signed report from an order. What does ClinicHub receive?",fa:"به یک گزارش امضاشده از یک درخواست، addendum اضافه می‌شود. ClinicHub چه چیزی دریافت می‌کند؟"},options:{en:["Nothing more","The result again as `amended`, with the addenda appended to the conclusion","Only the addendum's text"],fa:["چیز دیگری نه","دوباره جواب، به شکل `amended`، با addendumها اضافه‌شده به نتیجه‌گیری","فقط متن addendum"]},answer:1,why:{en:"Each addendum queues the result again so the clinic's copy matches.",fa:"هر addendum جواب را دوباره در صف می‌گذارد تا نسخه‌ی کلینیک جور باشد."}},{q:{en:"What does the accounting receive about a signed echo report?",fa:"حسابداری درباره‌ی یک گزارش اکوی امضاشده چه چیزی دریافت می‌کند؟"},options:{en:["The patient's name and the conclusion","The whole report as a PDF","An invoice to OHIP with the template's technical and professional fees, and no health information"],fa:["نام بیمار و نتیجه‌گیری","کل گزارش به شکل PDF","یک فاکتور به OHIP با هزینه‌ی فنی و حرفه‌ای قالب، بدون اطلاعات سلامت"]},answer:2,why:{en:"No patient and no findings leave; the id `report:{id}:signed` makes it sent once.",fa:"نه بیمار و نه یافته‌ها خارج می‌شوند؛ شناسه‌ی `report:{id}:signed` باعث می‌شود یک بار فرستاده شود."}}]},{id:"fe-app",group:"frontend",title:{en:"The pages and the API client",fa:"صفحه‌ها و API client"},files:["web/src/App.tsx","web/src/api.ts","web/src/main.tsx","web/src/theme.ts"],en:[{id:"routes",h:"Routes",p:["React 19 with React Router. The designer, users and audit pages are behind the permission they need; without it the route sends the user back. The print view drops the top bar, so the browser's Print gives the A4 report alone."],data:{kind:"routes"}},{id:"gate",h:"Before any page",p:["The app first asks for the settings and who is signed in. Nobody: the sign-in page, or the *Sign in with ClinicHub* button when connected. Someone with a password to change or two-factor to set up: only that page. Signing out when connected goes to `/api/auth/sso/signout`, which signs out of ClinicHub too."],examples:["gate","signout"]},{id:"client",h:"One typed client",p:["`api.ts` mirrors the C# records as TypeScript types and sends every call through `request`, which adds the CSRF and client-id headers, turns any error into an `ApiError` with the field errors of a 400, and on a 401 tells the app the session has ended."],examples:["request"]},{id:"signedout",h:"A session that ends anywhere",p:["When any call other than `/api/auth/*` answers 401, `request` fires a `clinicreport:signed-out` event on the window, and `App` listens for it and sets the user to nobody, which shows the sign-in page. So a session ended elsewhere (an administrator's change, *sign out everywhere*, ClinicHub refusing the re-check) is noticed by whatever page is open, without each page handling 401 itself. Calls to `/api/auth/*` are left out because a wrong password there is also a 401 and must stay on the sign-in form."],examples:["signedout"]},{id:"theme",h:"Dark first, decided before the first paint",p:["Echo and ECG rooms are dimmed, so the dark theme is the default; the choice is a per-browser convenience in `localStorage`, and a private window that refuses storage simply does not remember it. `main.tsx` applies it before React renders anything, so the page never flashes in the wrong theme. In the public demo a banner reminds visitors not to enter real patient information."],examples:["theme"]}],fa:[{id:"routes",h:"routeها",p:["React 19 با React Router. صفحه‌های designer، کاربران و audit پشت مجوزی هستند که لازم دارند؛ بدون آن route کاربر را برمی‌گرداند. نمای چاپ نوار بالا را ندارد، پس Print مرورگر فقط گزارش A4 را می‌دهد."],data:{kind:"routes"}},{id:"gate",h:"قبل از هر صفحه",p:["اپ اول تنظیمات و این‌که چه کسی وارد شده را می‌پرسد. هیچ‌کس: صفحه‌ی ورود، یا در حالت متصل دکمه‌ی *Sign in with ClinicHub*. کسی که رمزی برای عوض کردن یا دومرحله‌ای برای راه انداختن دارد: فقط همان صفحه. خروج در حالت متصل به `/api/auth/sso/signout` می‌رود، که از ClinicHub هم خارج می‌کند."],examples:["gate","signout"]},{id:"client",h:"یک client با type",p:["`api.ts` recordهای C# را به‌صورت typeهای TypeScript تکرار می‌کند و هر درخواست را از `request` رد می‌کند، که هدرهای CSRF و client-id را اضافه می‌کند، هر خطا را به یک `ApiError` با خطاهای فیلدِ یک 400 تبدیل می‌کند، و با 401 به اپ می‌گوید session تمام شده."],examples:["request"]},{id:"signedout",h:"نشستی که هر جا ممکن است تمام شود",p:["وقتی هر فراخوانی به‌جز `/api/auth/*` جواب 401 بدهد، `request` یک رویداد `clinicreport:signed-out` روی window می‌فرستد و `App` به آن گوش می‌دهد و کاربر را خالی می‌کند، که صفحه‌ی ورود را نشان می‌دهد. پس نشستی که جای دیگری تمام شده (تغییر یک مدیر، *sign out everywhere*، رد شدن چک دوباره توسط ClinicHub) را هر صفحه‌ای که باز است می‌فهمد، بی‌آن‌که هر صفحه خودش به 401 رسیدگی کند. فراخوانی‌های `/api/auth/*` کنار گذاشته شده‌اند، چون رمز اشتباه آن‌جا هم 401 است و باید روی فرم ورود بماند."],examples:["signedout"]},{id:"theme",h:"اول تیره، تصمیم‌گرفته قبل از اولین رسم",p:["اتاق‌های اکو و ECG کم‌نورند، پس تم تیره پیش‌فرض است؛ انتخاب یک راحتی مخصوص هر مرورگر در `localStorage` است، و پنجره‌ی خصوصی‌ای که storage را رد می‌کند فقط آن را به خاطر نمی‌سپارد. `main.tsx` قبل از این‌که React چیزی رسم کند آن را اعمال می‌کند، پس صفحه هیچ‌وقت با تم اشتباه چشمک نمی‌زند. در دموی عمومی یک بنر به بازدیدکننده‌ها یادآوری می‌کند که اطلاعات بیمار واقعی وارد نکنند."],examples:["theme"]}],examples:{gate:{title:{en:"Signed in, and nothing pending",fa:"وارد شده، و هیچ کار مانده‌ای نیست"},lang:"typescript",file:"web/src/App.tsx",from:"if (!settings || me === undefined)",lines:3},signout:{title:{en:"One sign-out, here and at ClinicHub",fa:"یک خروج، این‌جا و در ClinicHub"},lang:"typescript",file:"web/src/App.tsx",from:"const signOut = useCallback(async () => {",lines:9},request:{title:{en:"Every call goes through here",fa:"هر درخواست از این‌جا می‌گذرد"},lang:"typescript",file:"web/src/api.ts",from:"async function request<T>(method: string, url: string, body?: unknown): Promise<T> {",lines:21},signedout:{title:{en:"Every page hears the session end",fa:"همه‌ی صفحه‌ها پایان نشست را می‌شنوند"},lang:"typescript",file:"web/src/App.tsx",from:"const onSignedOut = () => setMe(null)",lines:3},theme:{title:{en:"Dark unless light was chosen",fa:"تیره، مگر روشن انتخاب شده باشد"},lang:"typescript",file:"web/src/theme.ts",from:"export function savedTheme(): Theme {",lines:7}},quiz:[{q:{en:"An administrator ends a user's sessions while the user has the worklist open. What does the user see on their next action?",fa:"مدیری نشست‌های یک کاربر را تمام می‌کند در حالی که او worklist را باز دارد. کاربر در کار بعدی‌اش چه می‌بیند؟"},options:{en:["An error message on the worklist","The sign-in page, because the 401 fires the signed-out event","Nothing until they reload"],fa:["یک پیام خطا روی worklist","صفحه‌ی ورود، چون 401 رویداد signed-out را می‌فرستد","تا وقتی صفحه را دوباره بارگذاری نکند هیچ"]},answer:1,why:{en:"`App` listens for `clinicreport:signed-out` and sets the user to nobody.",fa:"`App` به `clinicreport:signed-out` گوش می‌دهد و کاربر را خالی می‌کند."}},{q:{en:'Why are 401s from `/api/auth/*` not treated as "signed out"?',fa:"چرا 401های `/api/auth/*` به‌عنوان «خارج شده» حساب نمی‌شوند؟"},options:{en:["A wrong password there is also a 401 and must stay on the sign-in form","Those endpoints never answer 401","They are handled by ClinicHub"],fa:["رمز اشتباه آن‌جا هم 401 است و باید روی فرم ورود بماند","آن endpointها هیچ‌وقت 401 نمی‌دهند","ClinicHub به آن‌ها رسیدگی می‌کند"]},answer:0,why:{en:"The sign-in page shows the error itself, such as a missing two-factor code.",fa:"صفحه‌ی ورود خودش خطا را نشان می‌دهد، مثلاً نبود کد دومرحله‌ای."}},{q:{en:"A typist without `templates.design` opens `/templates/3` directly. What happens?",fa:"تایپیستی بدون `templates.design` مستقیم `/templates/3` را باز می‌کند. چه می‌شود؟"},options:{en:["The designer opens read-only","A 403 page","The route sends them back to `/templates`"],fa:["طراح فقط‌خواندنی باز می‌شود","یک صفحه‌ی 403","route او را به `/templates` برمی‌گرداند"]},answer:2,why:{en:"Routes behind a permission render a `Navigate` instead; the API would refuse the changes anyway.",fa:"routeهای پشت یک مجوز به‌جایش یک `Navigate` رسم می‌کنند؛ API به هر حال تغییرها را رد می‌کرد."}}]},{id:"data-sqlite",group:"data",title:{en:"SQLite, migrations and the demo",fa:"SQLite، migrationها و دمو"},files:["src/ClinicReport.Api/Data/ClinicReportDbContext.cs","src/ClinicReport.Api/Data/DatabaseInitializer.cs","src/ClinicReport.Api/Data/Migrations/20261021033045_OrderConfidentiality.cs","src/ClinicReport.Api/Program.cs"],en:[{id:"why",h:"Why SQLite",p:["A clinic's reporting fits in one file: no database server to run, back up or secure, and the backup is a copy of `/data`. The price is one writer at a time, which a clinic's typing never comes near, and few types: dates, booleans and money are stored as TEXT and INTEGER, which is why the tables here note the C# type each column holds."],examples:["sqlite"]},{id:"migrations",h:"EF Core migrations, applied at start",p:["The schema is EF Core's, eight migrations from `Initial` to `OrderConfidentiality`, applied by `MigrateAsync` when a database is opened (at start standalone, at a clinic's first sign-in connected). The tables on these pages are read from the model snapshot the migrations build."],examples:["migration","migrate"]},{id:"nocase",h:"User names in any case",p:["User names, role names and last names use SQLite's NOCASE collation, so `Admin` and `admin` are one user and a search by last name ignores case, in the database itself rather than in each query."],examples:["nocase"]},{id:"demo",h:"The demo starts over every day",p:["With `Demo:Enabled`, five synthetic patients (every MRN starts with `DEMO-`), three reports in progress and four one-click users are seeded; accounts and passwords are locked. With `Demo:ResetHourUtc`, the database is deleted and seeded again every day at that hour, so whatever visitors typed does not stay."],examples:["reset"]},{id:"secrets",h:"Secrets and keys in the container",p:["Settings can come from files in `/run/secrets`, one file per setting, the way Docker mounts secrets. The keys that encrypt the cookie and the two-factor secrets are kept in the data volume, so a redeploy does not sign everyone out."],examples:["secrets"]},{id:"tables",h:"The template tables",data:{kind:"tables",only:["Templates","TemplateVersions"]}}],fa:[{id:"why",h:"چرا SQLite",p:["گزارش‌نویسی یک کلینیک در یک فایل جا می‌شود: سرور دیتابیسی نیست که اجرا، backup یا امن شود، و backup یعنی یک کپی از `/data`. بهایش یک نویسنده در هر لحظه است، که تایپ یک کلینیک هیچ‌وقت به آن نزدیک نمی‌شود، و typeهای کم: تاریخ، boolean و پول به‌صورت TEXT و INTEGER ذخیره می‌شوند، و به همین دلیل جدول‌های این‌جا type C# هر ستون را هم می‌نویسند."],examples:["sqlite"]},{id:"migrations",h:"migrationهای EF Core، موقع بالا آمدن",p:["schema مال EF Core است، هشت migration از `Initial` تا `OrderConfidentiality`، که `MigrateAsync` هر وقت دیتابیسی باز شود اعمال می‌کند (در حالت مستقل موقع بالا آمدن، در حالت متصل در اولین ورود کلینیک). جدول‌های این صفحه‌ها از model snapshotی خوانده می‌شوند که migrationها می‌سازند."],examples:["migration","migrate"]},{id:"nocase",h:"نام کاربری با هر حروفی",p:["نام‌های کاربری، اسم نقش‌ها و نام‌های خانوادگی collation NOCASE در SQLite را دارند، پس `Admin` و `admin` یک کاربرند و جست‌وجو با نام خانوادگی به بزرگی و کوچکی حروف کاری ندارد، در خود دیتابیس نه در هر query."],examples:["nocase"]},{id:"demo",h:"دمو هر روز از نو شروع می‌شود",p:["با `Demo:Enabled`، پنج بیمار ساختگی (همه‌ی MRNها با `DEMO-` شروع می‌شوند)، سه گزارش در جریان و چهار کاربر یک‌کلیکی seed می‌شوند؛ حساب‌ها و رمزها قفل‌اند. با `Demo:ResetHourUtc`، دیتابیس هر روز در آن ساعت پاک و دوباره seed می‌شود، پس هر چه بازدیدکننده‌ها تایپ کرده‌اند نمی‌ماند."],examples:["reset"]},{id:"secrets",h:"secretها و کلیدها در container",p:["تنظیمات می‌توانند از فایل‌هایی در `/run/secrets` بیایند، هر تنظیم یک فایل، همان‌طور که Docker secretها را mount می‌کند. کلیدهایی که کوکی و secretهای دومرحله‌ای را رمز می‌کنند در volume داده نگه داشته می‌شوند، پس یک redeploy همه را بیرون نمی‌اندازد."],examples:["secrets"]},{id:"tables",h:"جدول‌های قالب",data:{kind:"tables",only:["Templates","TemplateVersions"]}}],examples:{sqlite:{title:{en:"One connection string",fa:"یک connection string"},lang:"csharp",file:"src/ClinicReport.Api/Program.cs",from:'var connectionString = builder.Configuration.GetConnectionString("ClinicReport")',lines:2},migration:{title:{en:"The latest migration",fa:"آخرین migration"},lang:"csharp",file:"src/ClinicReport.Api/Data/Migrations/20261021033045_OrderConfidentiality.cs",from:"protected override void Up(MigrationBuilder migrationBuilder)",lines:8},migrate:{title:{en:"Migrate, then seed",fa:"migrate، بعد seed"},lang:"csharp",file:"src/ClinicReport.Api/Data/DatabaseInitializer.cs",from:"if (wipe)",lines:11},nocase:{title:{en:"The users' columns",fa:"ستون‌های کاربران"},lang:"csharp",file:"src/ClinicReport.Api/Data/ClinicReportDbContext.cs",from:"b.Entity<AppUser>(e =>",lines:12},reset:{title:{en:"The next reset",fa:"ریست بعدی"},lang:"csharp",file:"src/ClinicReport.Api/Data/DatabaseInitializer.cs",from:"var next = new DateTimeOffset(now.Year",lines:4},secrets:{title:{en:"Secrets as files, keys in the volume",fa:"secretها به‌صورت فایل، کلیدها در volume"},lang:"csharp",file:"src/ClinicReport.Api/Program.cs",from:"// Secrets as files",to:'SetApplicationName("ClinicReport");'}},quiz:[{q:{en:"What is the price of keeping a clinic's reporting in one SQLite file?",fa:"هزینه‌ی نگه داشتن گزارش‌های یک کلینیک در یک فایل SQLite چیست؟"},options:{en:["One writer at a time, and few types (dates, booleans and money as TEXT and INTEGER)","No transactions","A separate server to back up"],fa:["یک نویسنده در هر لحظه، و نوع‌های کم (تاریخ، boolean و پول به شکل TEXT و INTEGER)","بدون تراکنش","یک سرور جدا برای پشتیبان‌گیری"]},answer:0,why:{en:"A clinic's typing never comes near the one-writer limit; the backup is a copy of `/data`.",fa:"تایپ یک کلینیک هیچ‌وقت به حد یک نویسنده نمی‌رسد؛ پشتیبان یک کپی از `/data` است."}},{q:{en:"Why do user names use the NOCASE collation?",fa:"چرا نام‌های کاربری collation‌ی NOCASE دارند؟"},options:{en:["To store them in upper case","So `Admin` and `admin` are one user, enforced in the database rather than in each query","Because SQLite requires it for unique indexes"],fa:["تا با حروف بزرگ ذخیره شوند","تا `Admin` و `admin` یک کاربر باشند، در خود دیتابیس و نه در هر کوئری","چون SQLite برای ایندکس یکتا لازمش دارد"]},answer:1,why:{en:"The collation also makes last-name searches ignore case.",fa:"این collation باعث می‌شود جستجوی نام خانوادگی هم به بزرگی و کوچکی حروف حساس نباشد."}},{q:{en:"With `Demo:ResetHourUtc` set, what happens at that hour?",fa:"با تنظیم `Demo:ResetHourUtc`، در آن ساعت چه می‌شود؟"},options:{en:["Only the reports are cleared","Visitors are signed out but data stays","The database is deleted and seeded again"],fa:["فقط گزارش‌ها پاک می‌شوند","بازدیدکننده‌ها خارج می‌شوند ولی داده می‌ماند","دیتابیس حذف و دوباره seed می‌شود"]},answer:2,why:{en:"Whatever visitors typed into the public demo does not stay.",fa:"هر چیزی که بازدیدکننده‌ها در دموی عمومی تایپ کرده‌اند نمی‌ماند."}}]}],a={project:e,repo:t,scan:i,groups:n,pages:s};export{a as default,n as groups,s as pages,e as project,t as repo,i as scan};
